INSERT INTO `1iPbG4KPq_zbs_mail` (`ID`, `zbs_site`, `zbs_team`, `zbs_owner`, `zbsmail_sender`, `zbsmail_subject`, `zbsmail_body`, `zbsmail_textbody`, `zbsmail_templateid`, `zbsmail_created`, `zbsmail_lastupdated`) VALUES
(14, 1, 1, 6, 'zbssmtp::noreply-portal-icg-agency', 'testing', '&lt;!DOCTYPE html PUBLIC &quot;-//W3C//DTD XHTML 1.0 Transitional//EN&quot; &quot;http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd&quot;&gt;\n&lt;html xmlns=&quot;http://www.w3.org/1999/xhtml&quot;&gt;\n    &lt;head&gt;\n        &lt;meta http-equiv=&quot;Content-Type&quot; content=&quot;text/html; charset=utf-8&quot; /&gt;\n        &lt;title&gt;##TITLE##&lt;/title&gt;\n\n        &lt;style type=&quot;text/css&quot;&gt;\n            /* ///////// CLIENT-SPECIFIC STYLES ///////// */\n            #outlook a {\n                padding: 0;\n            } /* Force Outlook to provide a &quot;view in browser&quot; message */\n            .ReadMsgBody {\n                width: 100%;\n            }\n            .ExternalClass {\n                width: 100%;\n            } /* Force Hotmail to display emails at full width */\n            .ExternalClass,\n            .ExternalClass p,\n            .ExternalClass span,\n            .ExternalClass font,\n            .ExternalClass td,\n            .ExternalClass div {\n                line-height: 100%;\n            } /* Force Hotmail to display normal line spacing */\n            body,\n            table,\n            td,\n            p,\n            a,\n            li,\n            blockquote {\n                -webkit-text-size-adjust: 100%;\n                -ms-text-size-adjust: 100%;\n            } /* Prevent WebKit and Windows mobile changing default text sizes */\n            table,\n            td {\n                mso-table-lspace: 0pt;\n                mso-table-rspace: 0pt;\n            } /* Remove spacing between tables in Outlook 2007 and up */\n            td ul li {\n                font-size: 16px;\n            }\n            /* ///////// RESET STYLES ///////// */\n            body {\n                margin: 0;\n                padding: 0;\n            }\n            img {\n                max-width: 100%;\n                border: 0;\n                line-height: 100%;\n                outline: none;\n                text-decoration: none;\n            }\n            table {\n                border-collapse: collapse !important;\n            }\n            .content {\n                width: 100%;\n                max-width: 600px;\n            }\n            .content img {\n                height: auto;\n                min-height: 1px;\n            }\n\n            #bodyTable {\n                margin: 0;\n                padding: 0;\n                width: 100% !important;\n            }\n            #bodyCell {\n                margin: 0;\n                padding: 0;\n            }\n            #bodyCellFooter {\n                margin: 0;\n                padding: 0;\n                width: 100% !important;\n                padding-top: 39px;\n                padding-bottom: 15px;\n            }\n            body {\n                margin: 0;\n                padding: 0;\n                min-width: 100% !important;\n            }\n            #templateContainerHeader {\n                border-top: 1px solid #e2e2e2;\n                border-left: 1px solid #e2e2e2;\n                border-right: 1px solid #e2e2e2;\n                font-size: 14px;\n                padding-top: 2.429em;\n                padding-bottom: 0.929em;\n            }\n            #templateContainerFootBrd {\n                border-bottom: 1px solid #e2e2e2;\n                border-left: 1px solid #e2e2e2;\n                border-right: 1px solid #e2e2e2;\n                background-clip: padding-box;\n                border-spacing: 0;\n                height: 10px;\n                width: 100% !important;\n            }\n            #templateContainer {\n                border-top: 1px solid #e2e2e2;\n                border-left: 1px solid #e2e2e2;\n                border-right: 1px solid #e2e2e2;\n                background-clip: padding-box;\n                border-spacing: 0;\n            }\n            #templateContainerMiddle {\n                border-left: 1px solid #e2e2e2;\n                border-right: 1px solid #e2e2e2;\n            }\n            #templateContainerMiddleBtm {\n                border-left: 1px solid #e2e2e2;\n                border-right: 1px solid #e2e2e2;\n                background-clip: padding-box;\n                border-spacing: 0;\n            }\n            #templateContainerLower {\n                border-left: 1px solid #e2e2e2;\n                border-right: 1px solid #e2e2e2;\n                border-bottom: 1px solid #e2e2e2;\n                background-clip: padding-box;\n                border-spacing: 0;\n            }\n\n            /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n            h1 {\n                color: #2e2e2e;\n                display: block;\n                font-family: Helvetica;\n                font-size: 26px;\n                line-height: 1.385em;\n                font-style: normal;\n                font-weight: normal;\n                letter-spacing: normal;\n                margin-top: 0;\n                margin-right: 0;\n                margin-bottom: 15px;\n                margin-left: 0;\n                text-align: left;\n            }\n\n            /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n            h2 {\n                color: #2e2e2e;\n                display: block;\n                font-family: Helvetica;\n                font-size: 22px;\n                line-height: 1.455em;\n                font-style: normal;\n                font-weight: normal;\n                letter-spacing: normal;\n                margin-top: 0;\n                margin-right: 0;\n                margin-bottom: 15px;\n                margin-left: 0;\n                text-align: left;\n            }\n\n            /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n            h3 {\n                color: #545454;\n                display: block;\n                font-family: Helvetica;\n                font-size: 18px;\n                line-height: 1.444em;\n                font-style: normal;\n                font-weight: normal;\n                letter-spacing: normal;\n                margin-top: 0;\n                margin-right: 0;\n                margin-bottom: 15px;\n                margin-left: 0;\n                text-align: left;\n            }\n\n            /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n            h4 {\n                color: #545454;\n                display: block;\n                font-family: Helvetica;\n                font-size: 14px;\n                line-height: 1.571em;\n                font-style: normal;\n                font-weight: normal;\n                letter-spacing: normal;\n                margin-top: 0;\n                margin-right: 0;\n                margin-bottom: 15px;\n                margin-left: 0;\n                text-align: left;\n            }\n\n            h5 {\n                color: #545454;\n                display: block;\n                font-family: Helvetica;\n                font-size: 13px;\n                line-height: 1.538em;\n                font-style: normal;\n                font-weight: normal;\n                letter-spacing: normal;\n                margin-top: 0;\n                margin-right: 0;\n                margin-bottom: 15px;\n                margin-left: 0;\n                text-align: left;\n            }\n\n            h6 {\n                color: #545454;\n                display: block;\n                font-family: Helvetica;\n                font-size: 12px;\n                line-height: 2em;\n                font-style: normal;\n                font-weight: normal;\n                letter-spacing: normal;\n                margin-top: 0;\n                margin-right: 0;\n                margin-bottom: 15px;\n                margin-left: 0;\n                text-align: left;\n            }\n\n            p {\n                color: #545454;\n                display: block;\n                font-family: Helvetica;\n                font-size: 16px;\n                line-height: 1.5em;\n                font-style: normal;\n                font-weight: normal;\n                letter-spacing: normal;\n                margin-top: 0;\n                margin-right: 0;\n                margin-bottom: 15px;\n                margin-left: 0;\n                text-align: left;\n            }\n\n            .unSubContent a:visited {\n                color: #a1a1a1;\n                text-decoration: underline;\n                font-weight: normal;\n            }\n            .unSubContent a:focus {\n                color: #a1a1a1;\n                text-decoration: underline;\n                font-weight: normal;\n            }\n            .unSubContent a:hover {\n                color: #a1a1a1;\n                text-decoration: underline;\n                font-weight: normal;\n            }\n            .unSubContent a:link {\n                color: #a1a1a1;\n                text-decoration: underline;\n                font-weight: normal;\n            }\n            .unSubContent a .yshortcuts {\n                color: #a1a1a1;\n                text-decoration: underline;\n                font-weight: normal;\n            }\n\n            .unSubContent h6 {\n                color: #a1a1a1;\n                font-size: 12px;\n                line-height: 1.5em;\n                margin-bottom: 0;\n            }\n\n            .bodyContent {\n                color: #505050;\n                font-family: Helvetica;\n                font-size: 14px;\n                line-height: 150%;\n                padding-top: 3.143em;\n                padding-right: 3.5em;\n                padding-left: 3.5em;\n                padding-bottom: 2.143em;\n                text-align: left;\n            }\n            .bodyContentCenter {\n                color: #505050;\n                font-family: Helvetica;\n                font-size: 14px;\n                line-height: 150%;\n                padding-top: 0em;\n                padding-right: 3.5em;\n                padding-left: 3.5em;\n                padding-bottom: 3em;\n                text-align: center;\n            }\n            .bodyContentCenter p {\n                margin-bottom: 0;\n                text-align: center;\n            }\n            .bodyContentCenter a.blue-btn {\n                margin-top: 0;\n            }\n            .bodyContentImage {\n                color: #505050;\n                font-family: Helvetica;\n                font-size: 14px;\n                line-height: 150%;\n                padding-top: 0;\n                padding-right: 3.571em;\n                padding-left: 3.571em;\n                padding-bottom: 2em;\n                text-align: left;\n            }\n\n            .bodyContentImage h4 {\n                color: #4e4e4e;\n                font-size: 13px;\n                line-height: 1.154em;\n                font-weight: normal;\n                margin-bottom: 0;\n            }\n            .bodyContentImage h5 {\n                color: #828282;\n                font-size: 12px;\n                line-height: 1.667em;\n                margin-bottom: 0;\n            }\n\n            /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email&#039;s main content links. Choose a color that helps them stand out from your text.\n  */\n            a:visited {\n                color: #3386e4;\n                text-decoration: none;\n            }\n            a:focus {\n                color: #3386e4;\n                text-decoration: none;\n            }\n            a:hover {\n                color: #3386e4;\n                text-decoration: none;\n            }\n            a:link {\n                color: #3386e4;\n                text-decoration: none;\n            }\n            a .yshortcuts {\n                color: #3386e4;\n                text-decoration: none;\n            }\n\n            .bodyContent img {\n                height: auto;\n                max-width: 498px;\n            }\n\n            .footerContent {\n                color: #808080;\n                font-family: Helvetica;\n                font-size: 10px;\n                line-height: 150%;\n                padding-top: 2em;\n                padding-right: 2em;\n                padding-bottom: 2em;\n                padding-left: 2em;\n                text-align: left;\n            }\n\n            /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email&#039;s footer links. Choose a color that helps them stand out from your text.\n  */\n            .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */ {\n                color: #606060;\n                font-weight: normal;\n                text-decoration: underline;\n            }\n\n            /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email&#039;s footer links. Choose a color that helps them stand out from your text.\n  */\n            #templateContainerImageFull {\n                border-left: 1px solid #e2e2e2;\n                border-right: 1px solid #e2e2e2;\n            }\n            #templateContainerImageCurve {\n                border-top: 1px solid #e2e2e2;\n                border-left: 1px solid #e2e2e2;\n                border-right: 1px solid #e2e2e2;\n                background-clip: padding-box;\n                border-collapse: separate !important;\n                border-spacing: 0;\n            }\n            #templateContainerImageCurve img {\n                background-clip: padding-box;\n            }\n            /*boom*/\n            .bodyContentImageFull p {\n                font-size: 0 !important;\n                margin-bottom: 0 !important;\n            }\n            .brdBottomPadd {\n                border-bottom: 1px solid #f0f0f0;\n            }\n            .brdBottomPadd .bodyContent {\n                padding-bottom: 2.286em;\n            }\n            a.blue-btn {\n                background: #5098ea;\n                display: inline-block;\n                color: #ffffff;\n                border-top: 10px solid #5098ea;\n                border-bottom: 10px solid #5098ea;\n                border-bottom: 10px solid #5098ea;\n                border-left: 20px solid #5098ea;\n                border-right: 20px solid #5098ea;\n                text-decoration: none;\n                font-size: 14px;\n                margin-top: 1em;\n                background-clip: padding-box;\n            }\n\n            @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n                body[yahoo] .hide {\n                    display: none !important;\n                }\n                body[yahoo] .buttonwrapper {\n                    background-color: transparent !important;\n                }\n                body[yahoo] .button {\n                    padding: 0px !important;\n                }\n                body[yahoo] .button a {\n                    background-color: #e05443;\n                    padding: 15px 15px 13px !important;\n                }\n                body[yahoo] .unsubscribe {\n                    font-size: 14px;\n                    display: block;\n                    margin-top: 0.714em;\n                    padding: 10px 50px;\n                    background: #2f3942;\n                    text-decoration: none !important;\n                }\n            }\n            /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n            @media only screen and (max-width: 480px) {\n                h1 {\n                    font-size: 34px !important;\n                }\n                h2 {\n                    font-size: 30px !important;\n                }\n                h3 {\n                    font-size: 24px !important;\n                }\n                h4 {\n                    font-size: 18px !important;\n                }\n                h5 {\n                    font-size: 16px !important;\n                }\n                h6 {\n                    font-size: 14px !important;\n                }\n                p {\n                    font-size: 18px !important;\n                }\n                .brdBottomPadd .bodyContent {\n                    padding-bottom: 2.286em !important;\n                }\n                .bodyContent {\n                    padding: 6% 5% 1% 6% !important;\n                }\n                .bodyContent img {\n                    max-width: 100% !important;\n                }\n                .bodyContentImage {\n                    padding: 3% 6% 6% 6% !important;\n                }\n                .bodyContentImage img {\n                    max-width: 100% !important;\n                }\n                .bodyContentImage h4 {\n                    font-size: 16px !important;\n                }\n                .bodyContentImage h5 {\n                    font-size: 15px !important;\n                    margin-top: 0;\n                }\n                td[class=&quot;bodyContentCenter&quot;] {\n                    padding: 6% 6% 6% 6% !important;\n                }\n            }\n            .ii a[href] {\n                color: inherit !important;\n            }\n            span &gt; a,\n            span &gt; a[href] {\n                color: inherit !important;\n            }\n            a &gt; span,\n            .ii a[href] &gt; span {\n                text-decoration: inherit !important;\n            }\n\n            /* WH additions */\n            .logo-wrap-100 img {\n                max-width: 100px !important;\n                margin-left: auto;\n                margin-right: auto;\n            }\n            .logo-wrap img {\n                max-width: 60px !important;\n                margin-left: auto;\n                margin-right: auto;\n            }\n        &lt;/style&gt;\n    &lt;/head&gt;\n\n    &lt;body yahoo bgcolor=&quot;#ffffff&quot;&gt;\n&lt;table border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;10&quot; bgcolor=&quot;#ffffff&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td&gt;&lt;!-- [if (gte mso 9)|(IE)]&gt;\n      &lt;table width=&quot;600&quot; align=&quot;center&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;&gt;\n        &lt;tr&gt;\n          &lt;td&gt;\n    &lt;![endif]--&gt;\n&lt;table class=&quot;content&quot; border=&quot;0&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot; align=&quot;center&quot; bgcolor=&quot;#ffffff&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td id=&quot;templateContainerHeader&quot; valign=&quot;top&quot;&gt;\n&lt;p style=&quot;text-align: center; margin: 0; padding: 0;&quot;&gt;&lt;!--&lt;img src=&quot;http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg&quot; style=&quot;display:inline-block;&quot; /&gt;\n						 &lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; style=&quot;max-width:100px&quot; /&gt;&lt;/a&gt; --&gt;&lt;/p&gt;\n&lt;div class=&quot;logo-wrap-100&quot; style=&quot;max-width: 100px; margin-left: auto; margin-right: auto;&quot;&gt;&lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img style=&quot;max-width: 100px;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddle&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; valign=&quot;top&quot;&gt;\n&lt;h3&gt;Hello ##CONTACT-FNAME##,&lt;/h3&gt;\n&lt;h2&gt;Say hello to ICG Belfast&lt;/h2&gt;\n&lt;p&gt;ICG is excited to share news of our official launch in &lt;a href=&quot;https://www.icg.agency/icg-belfast/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Northern Ireland&lt;/a&gt;.&lt;/p&gt;\n&lt;p&gt;We have established a dedicated base at the River House, located in the vibrant heart of the city&#039;s Cathedral Quarter, led by Digital Marketing Manager, Matt Holmes.&lt;/p&gt;\n&lt;p&gt;With a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas&#039; new store in Belfast with a PPC and local media campaign.&lt;/p&gt;\n&lt;p&gt;If you&#039;re interested in how ICG Belfast can support your business, please email &lt;a href=&quot;mailto:matt@icg.agency&quot;&gt;matt@icg.agency&lt;/a&gt; or &lt;a href=&quot;https://www.icg.agency/icg-belfast/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;find out more here&lt;/a&gt;.&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerImageCurve&quot; style=&quot;min-height: 15px;&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContentImageFull&quot; valign=&quot;top&quot;&gt;\n&lt;p style=&quot;text-align: center; margin: 0; padding: 0;&quot;&gt;&lt;img style=&quot;display: block;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg&quot; /&gt;&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddleBtm&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; style=&quot;border-top: 1px solid #f0f0f0;&quot; valign=&quot;top&quot;&gt;\n&lt;h2&gt;Come and see us at the Northern Marketing Festival&lt;/h2&gt;\n&lt;p&gt;The North&#039;s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on &lt;strong&gt;Thursday May 14th&lt;/strong&gt;.&lt;/p&gt;\n&lt;p&gt;Taking place at Victoria Warehouse, The Northern Marketing Festival is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.&lt;/p&gt;\n&lt;p&gt;Drop by to say hello - Simon, Julie and Dave would love to see you.&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerLower&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; valign=&quot;top&quot;&gt;\n&lt;h2&gt;Independent Agency of the Year Finalist&lt;/h2&gt;\n&lt;p&gt;Next Thursday we have an exciting evening in store&amp;hellip;. ICG has been shortlisted in the &lt;strong&gt;Prolific North Champions Awards 2026&lt;/strong&gt; taking place at The Point, Old Trafford.&lt;/p&gt;\n&lt;p&gt;We&#039;re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td id=&quot;bodyCellFooter&quot; class=&quot;unSubContent&quot; align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerFooter&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td valign=&quot;top&quot; width=&quot;100%&quot;&gt;\n&lt;p style=&quot;text-align: center;&quot;&gt;&lt;!--&lt;img src=&quot;http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg&quot; style=&quot;margin:0 auto 0 auto;display:inline-block;&quot; /&gt;--&gt;&lt;/p&gt;\n&lt;div class=&quot;logo-wrap&quot; style=&quot;max-width: 60px; margin-left: auto; margin-right: auto;&quot;&gt;&lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img style=&quot;max-width: 100px;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 9px;&quot;&gt;##BIZ-NAME##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center;&quot;&gt;##BIZ-CONTACT##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;##UNSUB-LINE##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;---&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;##POWERED-BY##&lt;/h6&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;!-- [if (gte mso 9)|(IE)]&gt;\n          &lt;/td&gt;\n        &lt;/tr&gt;\n    &lt;/table&gt;\n    &lt;![endif]--&gt;&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/body&gt;\n&lt;/html&gt;', 'Hello ##CONTACT-FNAME##,\n \nSay hello to ICG Belfast\n \nICG is excited to share news of our official launch in Northern Ireland: https://www.icg.agency/icg-belfast/.\n \nWe have established a dedicated base at the River House, located in the vibrant heart of the city&#039;s Cathedral Quarter, led by Digital Marketing Manager, Matt Holmes.\n \nWith a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas&#039; new store in Belfast with a PPC and local media campaign.\n \nIf you&#039;re interested in how ICG Belfast can support your business, please email matt@icg.agency: mailto:matt@icg.agency or find out more here: https://www.icg.agency/icg-belfast/.\n \nCome and see us at the Northern Marketing Festival\n \nThe North&#039;s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe&#039;re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -1, 1778145968, 1778228106),
(15, 1, 1, 6, 'zbssmtp::noreply-portal-icg-agency', '', '', '', -1, 1778228132, 1778228139),
(16, 1, 1, 6, '', '', '&lt;!DOCTYPE html PUBLIC &quot;-//W3C//DTD XHTML 1.0 Transitional//EN&quot; &quot;http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd&quot;&gt;\n&lt;html xmlns=&quot;http://www.w3.org/1999/xhtml&quot;&gt;\n&lt;head&gt;\n  &lt;meta http-equiv=&quot;Content-Type&quot; content=&quot;text/html; charset=utf-8&quot; /&gt;\n  &lt;title&gt;##TITLE##&lt;/title&gt;\n\n&lt;style type=&quot;text/css&quot;&gt;\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ CLIENT-SPECIFIC STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  #outlook a{padding:0;} /* Force Outlook to provide a &quot;view in browser&quot; message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ RESET STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email&#039;s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email&#039;s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email&#039;s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=&quot;bodyContentCenter&quot;] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span &gt; a, span &gt; a[href] {color: inherit !important;}\n  a &gt; span, .ii a[href] &gt; span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-100 img {\n    max-width: 100px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n&lt;/style&gt;\n&lt;/head&gt;\n\n&lt;body yahoo bgcolor=&quot;#ffffff&quot;&gt;\n&lt;table border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;10&quot; bgcolor=&quot;#ffffff&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td&gt;&lt;!-- [if (gte mso 9)|(IE)]&gt;\n      &lt;table width=&quot;600&quot; align=&quot;center&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;&gt;\n        &lt;tr&gt;\n          &lt;td&gt;\n    &lt;![endif]--&gt;\n&lt;table class=&quot;content&quot; border=&quot;0&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot; align=&quot;center&quot; bgcolor=&quot;#ffffff&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td id=&quot;templateContainerHeader&quot; valign=&quot;top&quot;&gt;\n&lt;p style=&quot;text-align: center; margin: 0; padding: 0;&quot;&gt;&lt;!--&lt;img src=&quot;http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg&quot; style=&quot;display:inline-block;&quot; /&gt;\n						 &lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; style=&quot;max-width:100px&quot; /&gt;&lt;/a&gt; --&gt;&lt;/p&gt;\n&lt;div class=&quot;logo-wrap-100&quot; style=&quot;max-width: 100px; margin-left: auto; margin-right: auto;&quot;&gt;&lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img style=&quot;max-width: 100px;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerTop&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; valign=&quot;top&quot;&gt;\n&lt;h3&gt;Hello ##CONTACT-FNAME##&lt;/h3&gt;\n&lt;h2&gt;&lt;strong&gt;We&#039;re announcing something new!&lt;/strong&gt;&lt;/h2&gt;\n&lt;p&gt;There are lots of ways of saying it, but this email template lets you announce something new. This is great for a new product update or service offering.&lt;br /&gt;&lt;br /&gt;You can edit this to contain any text you want to let your customers know about, simply click into the editor and type out your new announcement here!&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerImageCurve&quot; style=&quot;min-height: 15px;&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContentImageFull&quot; valign=&quot;top&quot;&gt;\n&lt;p style=&quot;text-align: center; margin: 0; padding: 0;&quot;&gt;&lt;img style=&quot;display: block;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg&quot; /&gt;&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddle&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; style=&quot;border-top: 1px solid #f0f0f0;&quot; valign=&quot;top&quot;&gt;\n&lt;h2&gt;Come and see us at the Northern Marketing Festival&lt;/h2&gt;\n&lt;p&gt;The North&#039;s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on &lt;strong&gt;Thursday May 14th&lt;/strong&gt;.&lt;/p&gt;\n&lt;p&gt;Taking place at Victoria Warehouse, The Northern Marketing Festival is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.&lt;/p&gt;\n&lt;p&gt;Drop by to say hello - Simon, Julie and Dave would love to see you.&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddle&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; valign=&quot;top&quot;&gt;\n&lt;h2&gt;Independent Agency of the Year Finalist&lt;/h2&gt;\n&lt;p&gt;Next Thursday we have an exciting evening in store&amp;hellip;. ICG has been shortlisted in the &lt;strong&gt;Prolific North Champions Awards 2026&lt;/strong&gt; taking place at The Point, Old Trafford.&lt;/p&gt;\n&lt;p&gt;We&#039;re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddleBtm&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr align=&quot;top&quot;&gt;\n&lt;td class=&quot;bodyContentImage&quot; valign=&quot;top&quot;&gt;\n&lt;table border=&quot;0&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td style=&quot;margin: 0; padding-top: 10px; line-height: 1;&quot; align=&quot;left&quot; valign=&quot;top&quot;&gt;\n&lt;p&gt;ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email &lt;a href=&quot;mailto:simon@icg.agency&quot;&gt;simon@icg.agency&lt;/a&gt;&lt;/p&gt;\n&lt;p&gt;&lt;a href=&quot;https://www.icg.agency&quot;&gt;www.icg.agency&lt;/a&gt;&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td id=&quot;bodyCellFooter&quot; class=&quot;unSubContent&quot; align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerFooter&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td valign=&quot;top&quot; width=&quot;100%&quot;&gt;\n&lt;p style=&quot;text-align: center;&quot;&gt;&lt;!--&lt;img src=&quot;http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg&quot; style=&quot;margin:0 auto 0 auto;display:inline-block;&quot; /&gt;--&gt;&lt;/p&gt;\n&lt;div class=&quot;logo-wrap&quot; style=&quot;max-width: 60px; margin-left: auto; margin-right: auto;&quot;&gt;&lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img style=&quot;max-width: 100px;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 9px;&quot;&gt;##BIZ-NAME##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center;&quot;&gt;##BIZ-CONTACT##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;##UNSUB-LINE##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;---&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;##POWERED-BY##&lt;/h6&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;!-- [if (gte mso 9)|(IE)]&gt;\n          &lt;/td&gt;\n        &lt;/tr&gt;\n    &lt;/table&gt;\n    &lt;![endif]--&gt;&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/body&gt;\n&lt;/html&gt;', 'Hello ##CONTACT-FNAME##\n \nWe&#039;re announcing something new!\n \nThere are lots of ways of saying it, but this email template lets you announce something new. This is great for a new product update or service offering.\n\nYou can edit this to contain any text you want to let your customers know about, simply click into the editor and type out your new announcement here!\n \nCome and see us at the Northern Marketing Festival\n \nThe North&#039;s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe&#039;re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \nwww.icg.agency: https://www.icg.agency/\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -201, 1778230190, 1778230190);
INSERT INTO `1iPbG4KPq_zbs_mail` (`ID`, `zbs_site`, `zbs_team`, `zbs_owner`, `zbsmail_sender`, `zbsmail_subject`, `zbsmail_body`, `zbsmail_textbody`, `zbsmail_templateid`, `zbsmail_created`, `zbsmail_lastupdated`) VALUES
(17, 1, 1, 6, 'zbssmtp::noreply-portal-icg-agency', 'fridaytest', '&lt;!DOCTYPE html PUBLIC &quot;-//W3C//DTD XHTML 1.0 Transitional//EN&quot; &quot;http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd&quot;&gt;\n&lt;html xmlns=&quot;http://www.w3.org/1999/xhtml&quot;&gt;\n&lt;head&gt;\n  &lt;meta http-equiv=&quot;Content-Type&quot; content=&quot;text/html; charset=utf-8&quot; /&gt;\n  &lt;title&gt;##TITLE##&lt;/title&gt;\n\n&lt;style type=&quot;text/css&quot;&gt;\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ CLIENT-SPECIFIC STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  #outlook a{padding:0;} /* Force Outlook to provide a &quot;view in browser&quot; message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ RESET STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email&#039;s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email&#039;s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email&#039;s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=&quot;bodyContentCenter&quot;] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span &gt; a, span &gt; a[href] {color: inherit !important;}\n  a &gt; span, .ii a[href] &gt; span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-100 img {\n    max-width: 100px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n&lt;/style&gt;\n&lt;/head&gt;\n\n&lt;body yahoo bgcolor=&quot;#ffffff&quot;&gt;\n&lt;table border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;10&quot; bgcolor=&quot;#ffffff&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td&gt;&lt;!-- [if (gte mso 9)|(IE)]&gt;\n      &lt;table width=&quot;600&quot; align=&quot;center&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;&gt;\n        &lt;tr&gt;\n          &lt;td&gt;\n    &lt;![endif]--&gt;\n&lt;table class=&quot;content&quot; border=&quot;0&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot; align=&quot;center&quot; bgcolor=&quot;#ffffff&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td id=&quot;templateContainerHeader&quot; valign=&quot;top&quot;&gt;\n&lt;p style=&quot;text-align: center; margin: 0; padding: 0;&quot;&gt;&lt;!--&lt;img src=&quot;http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg&quot; style=&quot;display:inline-block;&quot; /&gt;\n						 &lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; style=&quot;max-width:100px&quot; /&gt;&lt;/a&gt; --&gt;&lt;/p&gt;\n&lt;div class=&quot;logo-wrap-100&quot; style=&quot;max-width: 100px; margin-left: auto; margin-right: auto;&quot;&gt;&lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img style=&quot;max-width: 100px;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerTop&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; valign=&quot;top&quot;&gt;\n&lt;h3&gt;Hello ##CONTACT-FNAME##,&lt;/h3&gt;\n&lt;h2&gt;Say hello to ICG Belfast&lt;/h2&gt;\n&lt;p&gt;ICG is excited to share news of our official launch in &lt;a href=&quot;https://www.icg.agency/icg-belfast/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Northern Ireland&lt;/a&gt;.&lt;/p&gt;\n&lt;p&gt;We have established a dedicated base at the River House, located in the vibrant heart of the city&#039;s Cathedral Quarter, led by Digital Marketing Manager, Matt Holmes.&lt;/p&gt;\n&lt;p&gt;With a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas&#039; new store in Belfast with a PPC and local media campaign.&lt;/p&gt;\n&lt;p&gt;If you&#039;re interested in how ICG Belfast can support your business, please email &lt;a href=&quot;mailto:matt@icg.agency&quot;&gt;matt@icg.agency&lt;/a&gt; or &lt;a href=&quot;https://www.icg.agency/icg-belfast/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;find out more here&lt;/a&gt;.&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerImageCurve&quot; style=&quot;min-height: 15px;&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContentImageFull&quot; valign=&quot;top&quot;&gt;\n&lt;p style=&quot;text-align: center; margin: 0; padding: 0;&quot;&gt;&lt;img style=&quot;display: block;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg&quot; /&gt;&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddle&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; style=&quot;border-top: 1px solid #f0f0f0;&quot; valign=&quot;top&quot;&gt;\n&lt;h2&gt;&lt;strong&gt;Come and see us at the Northern Marketing Festival&lt;/strong&gt;&lt;/h2&gt;\n&lt;p&gt;The North&#039;s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on &lt;strong&gt;Thursday May 14th&lt;/strong&gt;.&lt;/p&gt;\n&lt;p&gt;Taking place at Victoria Warehouse, &lt;a href=&quot;https://www.prolificnorth.co.uk/northern-marketing-festival/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;The Northern Marketing Festival&lt;/a&gt; is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.&lt;/p&gt;\n&lt;p&gt;Drop by to say hello - Simon, Julie and Dave would love to see you.&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddle&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; valign=&quot;top&quot;&gt;\n&lt;h2&gt;&lt;strong&gt;Independent Agency of the Year Finalist&lt;/strong&gt;&lt;/h2&gt;\n&lt;p&gt;Next Thursday we have an exciting evening in store&amp;hellip;. ICG has been shortlisted in the &lt;strong&gt;Prolific North Champions Awards 2026&lt;/strong&gt; taking place at The Point, Old Trafford.&lt;/p&gt;\n&lt;p&gt;We&#039;re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddleBtm&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr align=&quot;top&quot;&gt;\n&lt;td class=&quot;bodyContentImage&quot; valign=&quot;top&quot;&gt;\n&lt;table border=&quot;0&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td style=&quot;margin: 0; padding-top: 10px; line-height: 1; border-top: 1px solid #f0f0f0;&quot; align=&quot;left&quot; valign=&quot;top&quot;&gt;\n&lt;p&gt;ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email &lt;a href=&quot;mailto:simon@icg.agency&quot;&gt;simon@icg.agency&lt;/a&gt;&lt;/p&gt;\n&lt;p&gt;&lt;a href=&quot;https://www.icg.agency&quot;&gt;www.icg.agency&lt;/a&gt;&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td id=&quot;bodyCellFooter&quot; class=&quot;unSubContent&quot; align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerFooter&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td valign=&quot;top&quot; width=&quot;100%&quot;&gt;\n&lt;p style=&quot;text-align: center;&quot;&gt;&lt;!--&lt;img src=&quot;http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg&quot; style=&quot;margin:0 auto 0 auto;display:inline-block;&quot; /&gt;--&gt;&lt;/p&gt;\n&lt;div class=&quot;logo-wrap&quot; style=&quot;max-width: 60px; margin-left: auto; margin-right: auto;&quot;&gt;&lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img style=&quot;max-width: 100px;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 9px;&quot;&gt;##BIZ-NAME##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center;&quot;&gt;##BIZ-CONTACT##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;##UNSUB-LINE##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;---&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;##POWERED-BY##&lt;/h6&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;!-- [if (gte mso 9)|(IE)]&gt;\n          &lt;/td&gt;\n        &lt;/tr&gt;\n    &lt;/table&gt;\n    &lt;![endif]--&gt;&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/body&gt;\n&lt;/html&gt;', 'Hello ##CONTACT-FNAME##,\n \nSay hello to ICG Belfast\n \nICG is excited to share news of our official launch in Northern Ireland: https://www.icg.agency/icg-belfast/.\n \nWe have established a dedicated base at the River House, located in the vibrant heart of the city&#039;s Cathedral Quarter, led by Digital Marketing Manager, Matt Holmes.\n \nWith a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas&#039; new store in Belfast with a PPC and local media campaign.\n \nIf you&#039;re interested in how ICG Belfast can support your business, please email matt@icg.agency: mailto:matt@icg.agency or find out more here: https://www.icg.agency/icg-belfast/.\n \nCome and see us at the Northern Marketing Festival\n \nThe North&#039;s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival: https://www.prolificnorth.co.uk/northern-marketing-festival/ is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe&#039;re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \nwww.icg.agency: https://www.icg.agency/\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -201, 1778230213, 1778231494),
(18, 1, 1, 6, '', '', '&lt;!DOCTYPE html PUBLIC &quot;-//W3C//DTD XHTML 1.0 Transitional//EN&quot; &quot;http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd&quot;&gt;\n&lt;html xmlns=&quot;http://www.w3.org/1999/xhtml&quot;&gt;\n&lt;head&gt;\n  &lt;meta http-equiv=&quot;Content-Type&quot; content=&quot;text/html; charset=utf-8&quot; /&gt;\n  &lt;title&gt;##TITLE##&lt;/title&gt;\n\n&lt;style type=&quot;text/css&quot;&gt;\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ CLIENT-SPECIFIC STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  #outlook a{padding:0;} /* Force Outlook to provide a &quot;view in browser&quot; message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ RESET STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email&#039;s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email&#039;s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email&#039;s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=&quot;bodyContentCenter&quot;] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span &gt; a, span &gt; a[href] {color: inherit !important;}\n  a &gt; span, .ii a[href] &gt; span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-100 img {\n    max-width: 100px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n&lt;/style&gt;\n&lt;/head&gt;\n\n&lt;body yahoo bgcolor=&quot;#ffffff&quot;&gt;\n&lt;table border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;10&quot; bgcolor=&quot;#ffffff&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td&gt;&lt;!-- [if (gte mso 9)|(IE)]&gt;\n      &lt;table width=&quot;600&quot; align=&quot;center&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;&gt;\n        &lt;tr&gt;\n          &lt;td&gt;\n    &lt;![endif]--&gt;\n&lt;table class=&quot;content&quot; border=&quot;0&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot; align=&quot;center&quot; bgcolor=&quot;#ffffff&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td id=&quot;templateContainerHeader&quot; valign=&quot;top&quot;&gt;\n&lt;p style=&quot;text-align: center; margin: 0; padding: 0;&quot;&gt;&lt;!--&lt;img src=&quot;http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg&quot; style=&quot;display:inline-block;&quot; /&gt;\n						 &lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; style=&quot;max-width:100px&quot; /&gt;&lt;/a&gt; --&gt;&lt;/p&gt;\n&lt;div class=&quot;logo-wrap-100&quot; style=&quot;max-width: 100px; margin-left: auto; margin-right: auto;&quot;&gt;&lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img style=&quot;max-width: 100px;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerTop&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; valign=&quot;top&quot;&gt;\n&lt;h3&gt;Hello ##CONTACT-FNAME##&lt;/h3&gt;\n&lt;h2&gt;&lt;strong&gt;We&#039;re announcing something new!&lt;/strong&gt;&lt;/h2&gt;\n&lt;p&gt;There are lots of ways of saying it, but this email template lets you announce something new. This is great for a new product update or service offering.&lt;br /&gt;&lt;br /&gt;You can edit this to contain any text you want to let your customers know about, simply click into the editor and type out your new announcement here!&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerImageCurve&quot; style=&quot;min-height: 15px;&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContentImageFull&quot; valign=&quot;top&quot;&gt;\n&lt;p style=&quot;text-align: center; margin: 0; padding: 0;&quot;&gt;&lt;img style=&quot;display: block;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg&quot; /&gt;&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddle&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; style=&quot;border-top: 1px solid #f0f0f0;&quot; valign=&quot;top&quot;&gt;\n&lt;h2&gt;Come and see us at the Northern Marketing Festival&lt;/h2&gt;\n&lt;p&gt;The North&#039;s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on &lt;strong&gt;Thursday May 14th&lt;/strong&gt;.&lt;/p&gt;\n&lt;p&gt;Taking place at Victoria Warehouse, The Northern Marketing Festival is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.&lt;/p&gt;\n&lt;p&gt;Drop by to say hello - Simon, Julie and Dave would love to see you.&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddle&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; valign=&quot;top&quot;&gt;\n&lt;h2&gt;Independent Agency of the Year Finalist&lt;/h2&gt;\n&lt;p&gt;Next Thursday we have an exciting evening in store&amp;hellip;. ICG has been shortlisted in the &lt;strong&gt;Prolific North Champions Awards 2026&lt;/strong&gt; taking place at The Point, Old Trafford.&lt;/p&gt;\n&lt;p&gt;We&#039;re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddleBtm&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr align=&quot;top&quot;&gt;\n&lt;td class=&quot;bodyContentImage&quot; valign=&quot;top&quot;&gt;\n&lt;table border=&quot;0&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td style=&quot;margin: 0; padding-top: 10px; line-height: 1;&quot; align=&quot;left&quot; valign=&quot;top&quot;&gt;\n&lt;p&gt;ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email &lt;a href=&quot;mailto:simon@icg.agency&quot;&gt;simon@icg.agency&lt;/a&gt;&lt;/p&gt;\n&lt;p&gt;&lt;a href=&quot;https://www.icg.agency&quot;&gt;www.icg.agency&lt;/a&gt;&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td id=&quot;bodyCellFooter&quot; class=&quot;unSubContent&quot; align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerFooter&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td valign=&quot;top&quot; width=&quot;100%&quot;&gt;\n&lt;p style=&quot;text-align: center;&quot;&gt;&lt;!--&lt;img src=&quot;http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg&quot; style=&quot;margin:0 auto 0 auto;display:inline-block;&quot; /&gt;--&gt;&lt;/p&gt;\n&lt;div class=&quot;logo-wrap&quot; style=&quot;max-width: 60px; margin-left: auto; margin-right: auto;&quot;&gt;&lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img style=&quot;max-width: 100px;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 9px;&quot;&gt;##BIZ-NAME##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center;&quot;&gt;##BIZ-CONTACT##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;##UNSUB-LINE##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;---&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;##POWERED-BY##&lt;/h6&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;!-- [if (gte mso 9)|(IE)]&gt;\n          &lt;/td&gt;\n        &lt;/tr&gt;\n    &lt;/table&gt;\n    &lt;![endif]--&gt;&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/body&gt;\n&lt;/html&gt;', 'Hello ##CONTACT-FNAME##\n \nWe&#039;re announcing something new!\n \nThere are lots of ways of saying it, but this email template lets you announce something new. This is great for a new product update or service offering.\n\nYou can edit this to contain any text you want to let your customers know about, simply click into the editor and type out your new announcement here!\n \nCome and see us at the Northern Marketing Festival\n \nThe North&#039;s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe&#039;re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \nwww.icg.agency: https://www.icg.agency/\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -201, 1778230220, 1778230220);
INSERT INTO `1iPbG4KPq_zbs_mail` (`ID`, `zbs_site`, `zbs_team`, `zbs_owner`, `zbsmail_sender`, `zbsmail_subject`, `zbsmail_body`, `zbsmail_textbody`, `zbsmail_templateid`, `zbsmail_created`, `zbsmail_lastupdated`) VALUES
(19, 1, 1, 6, '', '', '&lt;!DOCTYPE html PUBLIC &quot;-//W3C//DTD XHTML 1.0 Transitional//EN&quot; &quot;http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd&quot;&gt;\n&lt;html xmlns=&quot;http://www.w3.org/1999/xhtml&quot;&gt;\n&lt;head&gt;\n  &lt;meta http-equiv=&quot;Content-Type&quot; content=&quot;text/html; charset=utf-8&quot; /&gt;\n  &lt;title&gt;##TITLE##&lt;/title&gt;\n\n&lt;style type=&quot;text/css&quot;&gt;\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ CLIENT-SPECIFIC STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  #outlook a{padding:0;} /* Force Outlook to provide a &quot;view in browser&quot; message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ RESET STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email&#039;s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email&#039;s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email&#039;s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=&quot;bodyContentCenter&quot;] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span &gt; a, span &gt; a[href] {color: inherit !important;}\n  a &gt; span, .ii a[href] &gt; span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-100 img {\n    max-width: 100px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n&lt;/style&gt;\n&lt;/head&gt;\n\n&lt;body yahoo bgcolor=&quot;#ffffff&quot;&gt;\n&lt;table border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;10&quot; bgcolor=&quot;#ffffff&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td&gt;&lt;!-- [if (gte mso 9)|(IE)]&gt;\n      &lt;table width=&quot;600&quot; align=&quot;center&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;&gt;\n        &lt;tr&gt;\n          &lt;td&gt;\n    &lt;![endif]--&gt;\n&lt;table class=&quot;content&quot; border=&quot;0&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot; align=&quot;center&quot; bgcolor=&quot;#ffffff&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td id=&quot;templateContainerHeader&quot; valign=&quot;top&quot;&gt;\n&lt;p style=&quot;text-align: center; margin: 0; padding: 0;&quot;&gt;&lt;!--&lt;img src=&quot;http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg&quot; style=&quot;display:inline-block;&quot; /&gt;\n						 &lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; style=&quot;max-width:100px&quot; /&gt;&lt;/a&gt; --&gt;&lt;/p&gt;\n&lt;div class=&quot;logo-wrap-100&quot; style=&quot;max-width: 100px; margin-left: auto; margin-right: auto;&quot;&gt;&lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img style=&quot;max-width: 100px;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerTop&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; valign=&quot;top&quot;&gt;\n&lt;h3&gt;Hello ##CONTACT-FNAME##&lt;/h3&gt;\n&lt;h2&gt;&lt;strong&gt;We&#039;re announcing something new!&lt;/strong&gt;&lt;/h2&gt;\n&lt;p&gt;There are lots of ways of saying it, but this email template lets you announce something new. This is great for a new product update or service offering.&lt;br /&gt;&lt;br /&gt;You can edit this to contain any text you want to let your customers know about, simply click into the editor and type out your new announcement here!&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerImageCurve&quot; style=&quot;min-height: 15px;&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContentImageFull&quot; valign=&quot;top&quot;&gt;\n&lt;p style=&quot;text-align: center; margin: 0; padding: 0;&quot;&gt;&lt;img style=&quot;display: block;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg&quot; /&gt;&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddle&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; style=&quot;border-top: 1px solid #f0f0f0;&quot; valign=&quot;top&quot;&gt;\n&lt;h2&gt;Come and see us at the Northern Marketing Festival&lt;/h2&gt;\n&lt;p&gt;The North&#039;s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on &lt;strong&gt;Thursday May 14th&lt;/strong&gt;.&lt;/p&gt;\n&lt;p&gt;Taking place at Victoria Warehouse, The Northern Marketing Festival is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.&lt;/p&gt;\n&lt;p&gt;Drop by to say hello - Simon, Julie and Dave would love to see you.&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddle&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td class=&quot;bodyContent&quot; valign=&quot;top&quot;&gt;\n&lt;h2&gt;Independent Agency of the Year Finalist&lt;/h2&gt;\n&lt;p&gt;Next Thursday we have an exciting evening in store&amp;hellip;. ICG has been shortlisted in the &lt;strong&gt;Prolific North Champions Awards 2026&lt;/strong&gt; taking place at The Point, Old Trafford.&lt;/p&gt;\n&lt;p&gt;We&#039;re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerMiddleBtm&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr align=&quot;top&quot;&gt;\n&lt;td class=&quot;bodyContentImage&quot; valign=&quot;top&quot;&gt;\n&lt;table border=&quot;0&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td style=&quot;margin: 0; padding-top: 10px; line-height: 1;&quot; align=&quot;left&quot; valign=&quot;top&quot;&gt;\n&lt;p&gt;ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email &lt;a href=&quot;mailto:simon@icg.agency&quot;&gt;simon@icg.agency&lt;/a&gt;&lt;/p&gt;\n&lt;p&gt;&lt;a href=&quot;https://www.icg.agency&quot;&gt;www.icg.agency&lt;/a&gt;&lt;/p&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td id=&quot;bodyCellFooter&quot; class=&quot;unSubContent&quot; align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerFooter&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td valign=&quot;top&quot; width=&quot;100%&quot;&gt;\n&lt;p style=&quot;text-align: center;&quot;&gt;&lt;!--&lt;img src=&quot;http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg&quot; style=&quot;margin:0 auto 0 auto;display:inline-block;&quot; /&gt;--&gt;&lt;/p&gt;\n&lt;div class=&quot;logo-wrap&quot; style=&quot;max-width: 60px; margin-left: auto; margin-right: auto;&quot;&gt;&lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img style=&quot;max-width: 100px;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 9px;&quot;&gt;##BIZ-NAME##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center;&quot;&gt;##BIZ-CONTACT##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;##UNSUB-LINE##&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;---&lt;/h6&gt;\n&lt;h6 style=&quot;text-align: center; margin-top: 7px;&quot;&gt;##POWERED-BY##&lt;/h6&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;!-- [if (gte mso 9)|(IE)]&gt;\n          &lt;/td&gt;\n        &lt;/tr&gt;\n    &lt;/table&gt;\n    &lt;![endif]--&gt;&lt;/td&gt;\n&lt;/tr&gt;\n&lt;/tbody&gt;\n&lt;/table&gt;\n&lt;/body&gt;\n&lt;/html&gt;', 'Hello ##CONTACT-FNAME##\n \nWe&#039;re announcing something new!\n \nThere are lots of ways of saying it, but this email template lets you announce something new. This is great for a new product update or service offering.\n\nYou can edit this to contain any text you want to let your customers know about, simply click into the editor and type out your new announcement here!\n \nCome and see us at the Northern Marketing Festival\n \nThe North&#039;s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe&#039;re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \nwww.icg.agency: https://www.icg.agency/\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -201, 1778230250, 1778230250),
(20, 1, 1, 6, 'zbssmtp::enews-icg-agency', 'TestGroupsend', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <title>##TITLE##</title>\n\n<style type=\"text/css\">\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ CLIENT-SPECIFIC STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  #outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ RESET STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email\'s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=\"bodyContentCenter\"] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span > a, span > a[href] {color: inherit !important;}\n  a > span, .ii a[href] > span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-200 img {\n    max-width: 200px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n        <tr>\n          <td>\n    <![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg\" style=\"display:inline-block;\" />\n						 <a href=\"https://www.icg.agency/\"><img src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" style=\"max-width:200px\" /></a> --></p>\n<div class=\"logo-wrap-200\" style=\"max-width: 200px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 200px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerTop\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h3>Hello ##CONTACT-FNAME##,</h3>\n<h2><strong>Say hello to ICG Belfast</strong></h2>\n<p>ICG is excited to share news of our official launch in <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">Northern Ireland</a>.</p>\n<p>We have established a dedicated base at the River House, located in the vibrant heart of the Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matt Holmes.</p>\n<p>With a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.</p>\n<p>If you\'re interested in how ICG Belfast can support your business, please email <a href=\"mailto:matt@icg.agency\">matt@icg.agency</a> or <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">find out more here</a>.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerImageCurve\" style=\"min-height: 15px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContentImageFull\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><img style=\"display: block;\" src=\"https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg\" /></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"border-top: 1px solid #f0f0f0;\" valign=\"top\">\n<h2><strong>Come and see us at the Northern Marketing Festival</strong></h2>\n<p>The North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on <strong>Thursday May 14th</strong>.</p>\n<p>Taking place at Victoria Warehouse, <a href=\"https://www.prolificnorth.co.uk/northern-marketing-festival/\" target=\"_blank\" rel=\"noopener\">The Northern Marketing Festival</a> is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.</p>\n<p>Drop by to say hello - Simon, Julie and Dave would love to see you.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><strong>Independent Agency of the Year Finalist</strong></h2>\n<p>Next Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the <strong>Prolific North Champions Awards 2026</strong> taking place at The Point, Old Trafford.</p>\n<p>We\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" valign=\"top\">\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"margin: 0; padding-top: 10px; line-height: 1; border-top: 1px solid #f0f0f0;\" align=\"left\" valign=\"top\">\n<p style=\"padding-top: 20px;\">ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n<p><a href=\"https://www.icg.agency\">www.icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td valign=\"top\" width=\"100%\">\n<p style=\"text-align: center;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg\" style=\"margin:0 auto 0 auto;display:inline-block;\" />--></p>\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n<h6 style=\"text-align: center; margin-top: 9px;\">##BIZ-NAME##</h6>\n<h6 style=\"text-align: center;\">##BIZ-CONTACT##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">---</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##POWERED-BY##</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n          </td>\n        </tr>\n    </table>\n    <![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hello ##CONTACT-FNAME##,\n \nSay hello to ICG Belfast\n \nICG is excited to share news of our official launch in Northern Ireland: https://www.icg.agency/icg-belfast/.\n \nWe have established a dedicated base at the River House, located in the vibrant heart of the Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matt Holmes.\n \nWith a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.\n \nIf you\'re interested in how ICG Belfast can support your business, please email matt@icg.agency: mailto:matt@icg.agency or find out more here: https://www.icg.agency/icg-belfast/.\n \nCome and see us at the Northern Marketing Festival\n \nThe North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival: https://www.prolificnorth.co.uk/northern-marketing-festival/ is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store…. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \nwww.icg.agency: https://www.icg.agency/\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -201, 1778233781, 1778233952);
INSERT INTO `1iPbG4KPq_zbs_mail` (`ID`, `zbs_site`, `zbs_team`, `zbs_owner`, `zbsmail_sender`, `zbsmail_subject`, `zbsmail_body`, `zbsmail_textbody`, `zbsmail_templateid`, `zbsmail_created`, `zbsmail_lastupdated`) VALUES
(21, 1, 1, 6, 'zbssmtp::enews-icg-agency', '[Internal] - Say hello to ICG Belfast', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <title>##TITLE##</title>\n\n<style type=\"text/css\">\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ CLIENT-SPECIFIC STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  #outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ RESET STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email\'s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=\"bodyContentCenter\"] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span > a, span > a[href] {color: inherit !important;}\n  a > span, .ii a[href] > span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-200 img {\n    max-width: 200px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n        <tr>\n          <td>\n    <![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg\" style=\"display:inline-block;\" />\n						 <a href=\"https://www.icg.agency/\"><img src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" style=\"max-width:200px\" /></a> --></p>\n<div class=\"logo-wrap-200\" style=\"max-width: 200px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 200px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerTop\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h3>Hello ##CONTACT-FNAME##,</h3>\n<h2><strong>Say hello to ICG Belfast</strong></h2>\n<p>ICG is excited to share news of our official launch in <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">Northern Ireland</a>.</p>\n<p>We have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matt Holmes.</p>\n<p>With a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.</p>\n<p>If you\'re interested in how ICG Belfast can support your business, please email <a href=\"mailto:matt@icg.agency\">matt@icg.agency</a> or <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">find out more here</a>.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerImageCurve\" style=\"min-height: 15px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContentImageFull\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><img style=\"display: block;\" src=\"https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg\" /></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"border-top: 1px solid #f0f0f0;\" valign=\"top\">\n<h2><strong>Come and see us at the Northern Marketing Festival</strong></h2>\n<p>The North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on <strong>Thursday May 14th</strong>.</p>\n<p>Taking place at Victoria Warehouse, <a href=\"https://www.prolificnorth.co.uk/northern-marketing-festival/\" target=\"_blank\" rel=\"noopener\">The Northern Marketing Festival</a> is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.</p>\n<p>Drop by to say hello - Simon, Julie and Dave would love to see you.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><strong>Independent Agency of the Year Finalist</strong></h2>\n<p>Next Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the <strong>Prolific North Champions Awards 2026</strong> taking place at The Point, Old Trafford.</p>\n<p>We\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" valign=\"top\">\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"margin: 0; padding-top: 10px; line-height: 1; border-top: 1px solid #f0f0f0;\" align=\"left\" valign=\"top\">\n<p style=\"padding-top: 20px;\">ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n<p><a href=\"https://www.icg.agency\">www.icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td valign=\"top\" width=\"100%\">\n<p style=\"text-align: center;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg\" style=\"margin:0 auto 0 auto;display:inline-block;\" />--></p>\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n<h6 style=\"text-align: center; margin-top: 9px;\">##BIZ-NAME##</h6>\n<h6 style=\"text-align: center;\">##BIZ-CONTACT##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">---</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##POWERED-BY##</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n          </td>\n        </tr>\n    </table>\n    <![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hello ##CONTACT-FNAME##,\n \nSay hello to ICG Belfast\n \nICG is excited to share news of our official launch in Northern Ireland: https://www.icg.agency/icg-belfast/.\n \nWe have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matt Holmes.\n \nWith a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.\n \nIf you\'re interested in how ICG Belfast can support your business, please email matt@icg.agency: mailto:matt@icg.agency or find out more here: https://www.icg.agency/icg-belfast/.\n \nCome and see us at the Northern Marketing Festival\n \nThe North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival: https://www.prolificnorth.co.uk/northern-marketing-festival/ is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store…. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \nwww.icg.agency: https://www.icg.agency/\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -201, 1778234778, 1778235044),
(22, 1, 1, 6, 'zbssmtp::enews-icg-agency', '[Internal] - Say hello to ICG Belfast', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <title>##TITLE##</title>\n\n<style type=\"text/css\">\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ CLIENT-SPECIFIC STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  #outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ RESET STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email\'s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=\"bodyContentCenter\"] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span > a, span > a[href] {color: inherit !important;}\n  a > span, .ii a[href] > span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-200 img {\n    max-width: 200px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n        <tr>\n          <td>\n    <![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg\" style=\"display:inline-block;\" />\n						 <a href=\"https://www.icg.agency/\"><img src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" style=\"max-width:200px\" /></a> --></p>\n<div class=\"logo-wrap-200\" style=\"max-width: 200px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 200px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerTop\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h3>Hi ##CONTACT-FNAME##,</h3>\n<h2><strong>Say hello to ICG Belfast</strong></h2>\n<p>ICG is excited to share news of our official launch in <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">Northern Ireland</a>.</p>\n<p>We have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matt Holmes.</p>\n<p>With a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.</p>\n<p>If you\'re interested in how ICG Belfast can support your business, please email <a href=\"mailto:matt@icg.agency\">matt@icg.agency</a> or <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">find out more here</a>.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerImageCurve\" style=\"min-height: 15px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContentImageFull\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><img style=\"display: block;\" src=\"https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg\" /></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"border-top: 1px solid #f0f0f0;\" valign=\"top\">\n<h2><strong>Come and see us at the Northern Marketing Festival</strong></h2>\n<p>The North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on <strong>Thursday May 14th</strong>.</p>\n<p>Taking place at Victoria Warehouse, <a href=\"https://www.prolificnorth.co.uk/northern-marketing-festival/\" target=\"_blank\" rel=\"noopener\">The Northern Marketing Festival</a> is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.</p>\n<p>Drop by to say hello - Simon, Julie and Dave would love to see you.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><strong>Independent Agency of the Year Finalist</strong></h2>\n<p>Next Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the <strong>Prolific North Champions Awards 2026</strong> taking place at The Point, Old Trafford.</p>\n<p>We\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" valign=\"top\">\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"margin: 0; padding-top: 10px; line-height: 1; border-top: 1px solid #f0f0f0;\" align=\"left\" valign=\"top\">\n<p style=\"padding-top: 20px;\">ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n<p><a href=\"https://www.icg.agency\">www.icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td valign=\"top\" width=\"100%\">\n<p style=\"text-align: center;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg\" style=\"margin:0 auto 0 auto;display:inline-block;\" />--></p>\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n<h6 style=\"text-align: center; margin-top: 9px;\">##BIZ-NAME##</h6>\n<h6 style=\"text-align: center;\">##BIZ-CONTACT##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">---</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##POWERED-BY##</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n          </td>\n        </tr>\n    </table>\n    <![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hi ##CONTACT-FNAME##,\n \nSay hello to ICG Belfast\n \nICG is excited to share news of our official launch in Northern Ireland: https://www.icg.agency/icg-belfast/.\n \nWe have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matt Holmes.\n \nWith a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.\n \nIf you\'re interested in how ICG Belfast can support your business, please email matt@icg.agency: mailto:matt@icg.agency or find out more here: https://www.icg.agency/icg-belfast/.\n \nCome and see us at the Northern Marketing Festival\n \nThe North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival: https://www.prolificnorth.co.uk/northern-marketing-festival/ is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store…. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \nwww.icg.agency: https://www.icg.agency/\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -201, 1778235455, 1778235501);
INSERT INTO `1iPbG4KPq_zbs_mail` (`ID`, `zbs_site`, `zbs_team`, `zbs_owner`, `zbsmail_sender`, `zbsmail_subject`, `zbsmail_body`, `zbsmail_textbody`, `zbsmail_templateid`, `zbsmail_created`, `zbsmail_lastupdated`) VALUES
(23, 1, 1, 6, 'zbssmtp::enews-icg-agency', 'Say hello to ICG Belfast', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <title>##TITLE##</title>\n\n<style type=\"text/css\">\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ CLIENT-SPECIFIC STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  #outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ RESET STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email\'s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=\"bodyContentCenter\"] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span > a, span > a[href] {color: inherit !important;}\n  a > span, .ii a[href] > span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-200 img {\n    max-width: 200px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n        <tr>\n          <td>\n    <![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg\" style=\"display:inline-block;\" />\n						 <a href=\"https://www.icg.agency/\"><img src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" style=\"max-width:200px\" /></a> --></p>\n<div class=\"logo-wrap-200\" style=\"max-width: 200px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 200px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerTop\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h3>Hi ##CONTACT-FNAME##,</h3>\n<h2><strong>Say hello to ICG Belfast</strong></h2>\n<p>ICG is excited to share news of our official launch in <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">Northern Ireland</a>.</p>\n<p>We have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matthew Holmes.</p>\n<p>With a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.</p>\n<p>If you\'re interested in how ICG Belfast can support your business, please email <a href=\"mailto:matt@icg.agency\">matt@icg.agency</a> or <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">find out more here</a>.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerImageCurve\" style=\"min-height: 15px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContentImageFull\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><img style=\"display: block;\" src=\"https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg\" /></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"border-top: 1px solid #f0f0f0;\" valign=\"top\">\n<h2><strong>Come and see us at the Northern Marketing Festival</strong></h2>\n<p>The North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on <strong>Thursday May 14th</strong>.</p>\n<p>Taking place at Victoria Warehouse, <a href=\"https://www.prolificnorth.co.uk/northern-marketing-festival/\" target=\"_blank\" rel=\"noopener\">The Northern Marketing Festival</a> is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.</p>\n<p>Drop by to say hello - Simon, Julie and Dave would love to see you.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><strong>Independent Agency of the Year Finalist</strong></h2>\n<p>Next Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the <strong>Prolific North Champions Awards 2026</strong> taking place at The Point, Old Trafford.</p>\n<p>We\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" valign=\"top\">\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"margin: 0; padding-top: 10px; line-height: 1; border-top: 1px solid #f0f0f0;\" align=\"left\" valign=\"top\">\n<p style=\"padding-top: 20px;\">ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n<p><a href=\"https://www.icg.agency\">www.icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td valign=\"top\" width=\"100%\">\n<p style=\"text-align: center;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg\" style=\"margin:0 auto 0 auto;display:inline-block;\" />--></p>\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n<h6 style=\"text-align: center; margin-top: 9px;\">##BIZ-NAME##</h6>\n<h6 style=\"text-align: center;\">##BIZ-CONTACT##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">---</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##POWERED-BY##</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n          </td>\n        </tr>\n    </table>\n    <![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hi ##CONTACT-FNAME##,\n \nSay hello to ICG Belfast\n \nICG is excited to share news of our official launch in Northern Ireland: https://www.icg.agency/icg-belfast/.\n \nWe have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matthew Holmes.\n \nWith a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.\n \nIf you\'re interested in how ICG Belfast can support your business, please email matt@icg.agency: mailto:matt@icg.agency or find out more here: https://www.icg.agency/icg-belfast/.\n \nCome and see us at the Northern Marketing Festival\n \nThe North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival: https://www.prolificnorth.co.uk/northern-marketing-festival/ is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store…. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \nwww.icg.agency: https://www.icg.agency/\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -201, 1778236731, 1784115722),
(24, 1, 1, 6, 'zbssmtp::enews-icg-agency', 'Say hello to ICG Belfast', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <title>##TITLE##</title>\n\n<style type=\"text/css\">\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ CLIENT-SPECIFIC STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  #outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ RESET STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email\'s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=\"bodyContentCenter\"] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span > a, span > a[href] {color: inherit !important;}\n  a > span, .ii a[href] > span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-200 img {\n    max-width: 200px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n        <tr>\n          <td>\n    <![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg\" style=\"display:inline-block;\" />\n						 <a href=\"https://www.icg.agency/\"><img src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" style=\"max-width:200px\" /></a> --></p>\n<div class=\"logo-wrap-200\" style=\"max-width: 200px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 200px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerTop\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h3>Hi ##CONTACT-FNAME##,</h3>\n<h2><strong>Say hello to ICG Belfast</strong></h2>\n<p>ICG is excited to share news of our official launch in <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">Northern Ireland</a>.</p>\n<p>We have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matthew Holmes.</p>\n<p>With a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.</p>\n<p>If you\'re interested in how ICG Belfast can support your business, please email <a href=\"mailto:matt@icg.agency\">matt@icg.agency</a> or <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">find out more here</a>.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerImageCurve\" style=\"min-height: 15px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContentImageFull\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><img style=\"display: block;\" src=\"https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg\" /></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"border-top: 1px solid #f0f0f0;\" valign=\"top\">\n<h2><strong>Come and see us at the Northern Marketing Festival</strong></h2>\n<p>The North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on <strong>Thursday May 14th</strong>.</p>\n<p>Taking place at Victoria Warehouse, <a href=\"https://www.prolificnorth.co.uk/northern-marketing-festival/\" target=\"_blank\" rel=\"noopener\">The Northern Marketing Festival</a> is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.</p>\n<p>Drop by to say hello - Simon, Julie and Dave would love to see you.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><strong>Independent Agency of the Year Finalist</strong></h2>\n<p>Next Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the <strong>Prolific North Champions Awards 2026</strong> taking place at The Point, Old Trafford.</p>\n<p>We\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" valign=\"top\">\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"margin: 0; padding-top: 10px; line-height: 1; border-top: 1px solid #f0f0f0;\" align=\"left\" valign=\"top\">\n<p style=\"padding-top: 20px;\">ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n<p><a href=\"https://www.icg.agency\">www.icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td valign=\"top\" width=\"100%\">\n<p style=\"text-align: center;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg\" style=\"margin:0 auto 0 auto;display:inline-block;\" />--></p>\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n<h6 style=\"text-align: center; margin-top: 9px;\">##BIZ-NAME##</h6>\n<h6 style=\"text-align: center;\">##BIZ-CONTACT##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">---</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##POWERED-BY##</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n          </td>\n        </tr>\n    </table>\n    <![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hi ##CONTACT-FNAME##,\n \nSay hello to ICG Belfast\n \nICG is excited to share news of our official launch in Northern Ireland: https://www.icg.agency/icg-belfast/.\n \nWe have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matthew Holmes.\n \nWith a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.\n \nIf you\'re interested in how ICG Belfast can support your business, please email matt@icg.agency: mailto:matt@icg.agency or find out more here: https://www.icg.agency/icg-belfast/.\n \nCome and see us at the Northern Marketing Festival\n \nThe North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival: https://www.prolificnorth.co.uk/northern-marketing-festival/ is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store…. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \nwww.icg.agency: https://www.icg.agency/\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -201, 1778236994, 1778237065);
INSERT INTO `1iPbG4KPq_zbs_mail` (`ID`, `zbs_site`, `zbs_team`, `zbs_owner`, `zbsmail_sender`, `zbsmail_subject`, `zbsmail_body`, `zbsmail_textbody`, `zbsmail_templateid`, `zbsmail_created`, `zbsmail_lastupdated`) VALUES
(25, 1, 1, 6, 'zbssmtp::enews-icg-agency', 'Say hello to ICG Belfast', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <title>##TITLE##</title>\n\n<style type=\"text/css\">\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ CLIENT-SPECIFIC STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  #outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ RESET STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email\'s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=\"bodyContentCenter\"] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span > a, span > a[href] {color: inherit !important;}\n  a > span, .ii a[href] > span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-200 img {\n    max-width: 200px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n        <tr>\n          <td>\n    <![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg\" style=\"display:inline-block;\" />\n						 <a href=\"https://www.icg.agency/\"><img src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" style=\"max-width:200px\" /></a> --></p>\n<div class=\"logo-wrap-200\" style=\"max-width: 200px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 200px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerTop\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h3>Hi ##CONTACT-FNAME##,</h3>\n<h2><strong>Say hello to ICG Belfast</strong></h2>\n<p>ICG is excited to share news of our official launch in <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">Northern Ireland</a>.</p>\n<p>We have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matthew Holmes.</p>\n<p>With a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.</p>\n<p>If you\'re interested in how ICG Belfast can support your business, please email <a href=\"mailto:matt@icg.agency\">matt@icg.agency</a> or <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">find out more here</a>.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerImageCurve\" style=\"min-height: 15px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContentImageFull\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><img style=\"display: block;\" src=\"https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg\" /></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"border-top: 1px solid #f0f0f0;\" valign=\"top\">\n<h2><strong>Come and see us at the Northern Marketing Festival</strong></h2>\n<p>The North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on <strong>Thursday May 14th</strong>.</p>\n<p>Taking place at Victoria Warehouse, <a href=\"https://www.prolificnorth.co.uk/northern-marketing-festival/\" target=\"_blank\" rel=\"noopener\">The Northern Marketing Festival</a> is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.</p>\n<p>Drop by to say hello - Simon, Julie and Dave would love to see you.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><strong>Independent Agency of the Year Finalist</strong></h2>\n<p>Next Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the <strong>Prolific North Champions Awards 2026</strong> taking place at The Point, Old Trafford.</p>\n<p>We\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" valign=\"top\">\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"margin: 0; padding-top: 10px; line-height: 1; border-top: 1px solid #f0f0f0;\" align=\"left\" valign=\"top\">\n<p style=\"padding-top: 20px;\">ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n<p><a href=\"https://www.icg.agency\">www.icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td valign=\"top\" width=\"100%\">\n<p style=\"text-align: center;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg\" style=\"margin:0 auto 0 auto;display:inline-block;\" />--></p>\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n<h6 style=\"text-align: center; margin-top: 9px;\">##BIZ-NAME##</h6>\n<h6 style=\"text-align: center;\">##BIZ-CONTACT##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">---</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##POWERED-BY##</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n          </td>\n        </tr>\n    </table>\n    <![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hi ##CONTACT-FNAME##,\n \nSay hello to ICG Belfast\n \nICG is excited to share news of our official launch in Northern Ireland: https://www.icg.agency/icg-belfast/.\n \nWe have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matthew Holmes.\n \nWith a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.\n \nIf you\'re interested in how ICG Belfast can support your business, please email matt@icg.agency: mailto:matt@icg.agency or find out more here: https://www.icg.agency/icg-belfast/.\n \nCome and see us at the Northern Marketing Festival\n \nThe North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival: https://www.prolificnorth.co.uk/northern-marketing-festival/ is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store…. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \nwww.icg.agency: https://www.icg.agency/\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -201, 1778237447, 1778237870),
(26, 1, 1, 6, 'zbssmtp::enews-icg-agency', 'Say hello to ICG Belfast', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <title>##TITLE##</title>\n\n<style type=\"text/css\">\n  /* ///////// CLIENT-SPECIFIC STYLES ///////// */\n  #outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* ///////// RESET STYLES ///////// */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email\'s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=\"bodyContentCenter\"] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span > a, span > a[href] {color: inherit !important;}\n  a > span, .ii a[href] > span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-200 img {\n    max-width: 200px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n        <tr>\n          <td>\n    <![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg\" style=\"display:inline-block;\" />\n						 <a href=\"https://www.icg.agency/\"><img src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" style=\"max-width:200px\" /></a> --></p>\n<div class=\"logo-wrap-200\" style=\"max-width: 200px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 200px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerTop\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h3>Hi ##CONTACT-FNAME##,</h3>\n<h2><strong>Say hello to ICG Belfast</strong></h2>\n<p>ICG is excited to share news of our official launch in <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">Northern Ireland</a>.</p>\n<p>We have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matthew Holmes.</p>\n<p>With a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.</p>\n<p>If you\'re interested in how ICG Belfast can support your business, please email <a href=\"mailto:matt@icg.agency\">matt@icg.agency</a> or <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">find out more here</a>.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerImageCurve\" style=\"min-height: 15px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContentImageFull\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><img style=\"display: block;\" src=\"https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg\" /></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"border-top: 1px solid #f0f0f0;\" valign=\"top\">\n<h2><strong>Come and see us at the Northern Marketing Festival</strong></h2>\n<p>The North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on <strong>Thursday May 14th</strong>.</p>\n<p>Taking place at Victoria Warehouse, <a href=\"https://www.prolificnorth.co.uk/northern-marketing-festival/\" target=\"_blank\" rel=\"noopener\">The Northern Marketing Festival</a> is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.</p>\n<p>Drop by to say hello - Simon, Julie and Dave would love to see you.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><strong>Independent Agency of the Year Finalist</strong></h2>\n<p>Next Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the <strong>Prolific North Champions Awards 2026</strong> taking place at The Point, Old Trafford.</p>\n<p>We\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" valign=\"top\">\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"margin: 0; padding-top: 10px; line-height: 1; border-top: 1px solid #f0f0f0;\" align=\"left\" valign=\"top\">\n<p style=\"padding-top: 20px;\">ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n<p><a href=\"https://www.icg.agency\">www.icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td valign=\"top\" width=\"100%\">\n<p style=\"text-align: center;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg\" style=\"margin:0 auto 0 auto;display:inline-block;\" />--></p>\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n<h6 style=\"text-align: center; margin-top: 9px;\">##BIZ-NAME##</h6>\n<h6 style=\"text-align: center;\">##BIZ-CONTACT##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">---</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##POWERED-BY##</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n          </td>\n        </tr>\n    </table>\n    <![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hi ##CONTACT-FNAME##,\n \nSay hello to ICG Belfast\n \nICG is excited to share news of our official launch in Northern Ireland: https://www.icg.agency/icg-belfast/.\n \nWe have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matthew Holmes.\n \nWith a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.\n \nIf you\'re interested in how ICG Belfast can support your business, please email matt@icg.agency: mailto:matt@icg.agency or find out more here: https://www.icg.agency/icg-belfast/.\n \nCome and see us at the Northern Marketing Festival\n \nThe North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival: https://www.prolificnorth.co.uk/northern-marketing-festival/ is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store…. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \nwww.icg.agency: https://www.icg.agency/\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -1, 1778238128, 1778240448);
INSERT INTO `1iPbG4KPq_zbs_mail` (`ID`, `zbs_site`, `zbs_team`, `zbs_owner`, `zbsmail_sender`, `zbsmail_subject`, `zbsmail_body`, `zbsmail_textbody`, `zbsmail_templateid`, `zbsmail_created`, `zbsmail_lastupdated`) VALUES
(27, 1, 1, 6, 'zbssmtp::enews-icg-agency', 'Say hello to ICG Belfast', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <title>##TITLE##</title>\n\n<style type=\"text/css\">\n  /* ///////// CLIENT-SPECIFIC STYLES ///////// */\n  #outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* ///////// RESET STYLES ///////// */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email\'s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=\"bodyContentCenter\"] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span > a, span > a[href] {color: inherit !important;}\n  a > span, .ii a[href] > span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-200 img {\n    max-width: 200px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n        <tr>\n          <td>\n    <![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg\" style=\"display:inline-block;\" />\n						 <a href=\"https://www.icg.agency/\"><img src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" style=\"max-width:200px\" /></a> --></p>\n<div class=\"logo-wrap-200\" style=\"max-width: 200px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 200px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerTop\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h3>Hi ##CONTACT-FNAME##,</h3>\n<h2><strong>Say hello to ICG Belfast</strong></h2>\n<p>ICG is excited to share news of our official launch in <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">Northern Ireland</a>.</p>\n<p>We have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matthew Holmes.</p>\n<p>With a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.</p>\n<p>If you\'re interested in how ICG Belfast can support your business, please email <a href=\"mailto:matt@icg.agency\">matt@icg.agency</a> or <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">find out more here</a>.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerImageCurve\" style=\"min-height: 15px;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContentImageFull\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><img style=\"display: block;\" src=\"https://portal.icg.agency/wp-content/uploads/2026/05/ICG_Belfast_Office_Email.jpg\" /></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"border-top: 1px solid #f0f0f0;\" valign=\"top\">\n<h2><strong>Come and see us at the Northern Marketing Festival</strong></h2>\n<p>The North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on <strong>Thursday May 14th</strong>.</p>\n<p>Taking place at Victoria Warehouse, <a href=\"https://www.prolificnorth.co.uk/northern-marketing-festival/\" target=\"_blank\" rel=\"noopener\">The Northern Marketing Festival</a> is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.</p>\n<p>Drop by to say hello - Simon, Julie and Dave would love to see you.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><strong>Independent Agency of the Year Finalist</strong></h2>\n<p>Next Thursday we have an exciting evening in store&hellip;. ICG has been shortlisted in the <strong>Prolific North Champions Awards 2026</strong> taking place at The Point, Old Trafford.</p>\n<p>We\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" valign=\"top\">\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"margin: 0; padding-top: 10px; line-height: 1; border-top: 1px solid #f0f0f0;\" align=\"left\" valign=\"top\">\n<p style=\"padding-top: 20px;\">ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n<p><a href=\"https://www.icg.agency\">www.icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td valign=\"top\" width=\"100%\">\n<p style=\"text-align: center;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg\" style=\"margin:0 auto 0 auto;display:inline-block;\" />--></p>\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n<h6 style=\"text-align: center; margin-top: 9px;\">##BIZ-NAME##</h6>\n<h6 style=\"text-align: center;\">##BIZ-CONTACT##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">---</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##POWERED-BY##</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n          </td>\n        </tr>\n    </table>\n    <![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hi ##CONTACT-FNAME##,\n \nSay hello to ICG Belfast\n \nICG is excited to share news of our official launch in Northern Ireland: https://www.icg.agency/icg-belfast/.\n \nWe have established a dedicated base at the River House, located in the vibrant heart of Belfast\'s Cathedral Quarter, led by Digital Marketing Manager, Matthew Holmes.\n \nWith a strong foundation already established in the area, including the City of Derry Airport and local IVECO dealership NI Trucks, we have expanded our reach to provide direct, face-to-face support to businesses throughout the region. We recently launched Designer Sofas\' new store in Belfast with a PPC and local media campaign.\n \nIf you\'re interested in how ICG Belfast can support your business, please email matt@icg.agency: mailto:matt@icg.agency or find out more here: https://www.icg.agency/icg-belfast/.\n \nCome and see us at the Northern Marketing Festival\n \nThe North\'s celebration of marketing and creativity is back - and we will be exhibiting at the Manchester event next week on Thursday May 14th.\n \nTaking place at Victoria Warehouse, The Northern Marketing Festival: https://www.prolificnorth.co.uk/northern-marketing-festival/ is a fantastic opportunity to talk creativity and data as well as forge new marketing connections, with speakers from brands including Sky, PG Tips, Uber and Co-op Live.\n \nDrop by to say hello - Simon, Julie and Dave would love to see you.\n \nIndependent Agency of the Year Finalist\n \nNext Thursday we have an exciting evening in store…. ICG has been shortlisted in the Prolific North Champions Awards 2026 taking place at The Point, Old Trafford.\n \nWe\'re up for two awards - Independent Agency of the Year (Medium) and Not-for-Profit Campaign of the Year, recognising our work with The Big Food Project. Fingers-crossed!\n \nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \nwww.icg.agency: https://www.icg.agency/\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -1, 1778238302, 1778240526),
(28, 1, 1, 6, 'zbssmtp::enews-icg-agency', 'test-outofoffice', '', '', -1, 1778248217, 1778248222),
(29, 1, 1, 2, 'zbssmtp::enews-icg-agency', 'Celebrating another long-standing client partnership', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <title>##TITLE##</title>\n\n<style type=\"text/css\">\n  /* ///////// CLIENT-SPECIFIC STYLES ///////// */\n  #outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* ///////// RESET STYLES ///////// */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email\'s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=\"bodyContentCenter\"] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span > a, span > a[href] {color: inherit !important;}\n  a > span, .ii a[href] > span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-200 img {\n    max-width: 200px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n        <tr>\n          <td>\n    <![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg\" style=\"display:inline-block;\" />\n						 <a href=\"https://www.icg.agency/\"><img src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" style=\"max-width:200px\" /></a> --></p>\n<div class=\"logo-wrap-200\" style=\"max-width: 200px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 200px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerTop\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h3>Hi ##CONTACT-FNAME##,</h3>\n<h2><strong>Celebrating another long-standing client partnership</strong></h2>\n<p>We are super proud of our 20-year partnership with League Football Education.</p>\n<p>In the last two decades we\'ve helped the charity shape how it communicates and connects with thousands of young apprentice footballers, their families, clubs and education providers across the country.</p>\n<p>With all eyes on tonight&rsquo;s match, what makes this partnership genuinely rewarding is seeing how LFE\'s apprentices progress through their careers - including Jude Bellingham, a former LFE apprentice.</p>\n<p><a href=\"https://www.icg.agency/blog/20-years-on-the-pitch-together/\">Read more</a> about long standing partnership with LFE.</p>\n<p><strong>Come on England!</strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\"><img src=\"https://portal.icg.agency/wp-content/uploads/2026/07/LFExICG_20years_Eshot.jpg\" alt=\"LFE x ICG 20 years\" width=\"1000\" height=\"400\" /><br /><br /></td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"border-top: 1px solid #f0f0f0;\" valign=\"top\">\n<h2><strong>Fresh thinking from MAD//Fest London 2026</strong></h2>\n<p>In the fast moving world of marketing, we are always hungry for the latest industry insights.&nbsp;</p>\n<p>Last week two members of the team joined thousands of fellow marketers, brands and agencies at MAD//Fest London 2026, one of the UK\'s biggest marketing festivals.&nbsp;</p>\n<p><a href=\"https://www.icg.agency/blog/fresh-thinking-from-mad-fest-london-2026/\">Read more</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><strong>We are a BIBAS finalist</strong></h2>\n<p>ICG is pleased to have been shortlisted in the BIBAs - Lancashire\'s premier business awards.&nbsp;</p>\n<p>We are competing in the Creative, Digital &amp; Marketing Business of the Year category - see you at the awards ceremony on September 18 at the Blackpool Tower Ballroom.&nbsp;</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" valign=\"top\">\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"margin: 0; padding-top: 10px; line-height: 1; border-top: 1px solid #f0f0f0;\" align=\"left\" valign=\"top\">\n<p style=\"padding-top: 20px;\">ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n<p><a href=\"https://www.icg.agency\">www.icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td valign=\"top\" width=\"100%\">\n<p style=\"text-align: center;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg\" style=\"margin:0 auto 0 auto;display:inline-block;\" />--></p>\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n<h6 style=\"text-align: center; margin-top: 9px;\">##BIZ-NAME##</h6>\n<h6 style=\"text-align: center;\">##BIZ-CONTACT##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">---</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n          </td>\n        </tr>\n    </table>\n    <![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hi ##CONTACT-FNAME##,\n \nCelebrating another long-standing client partnership\n \nWe are super proud of our 20-year partnership with League Football Education.\n \nIn the last two decades we\'ve helped the charity shape how it communicates and connects with thousands of young apprentice footballers, their families, clubs and education providers across the country.\n \nWith all eyes on tonight’s match, what makes this partnership genuinely rewarding is seeing how LFE\'s apprentices progress through their careers - including Jude Bellingham, a former LFE apprentice.\n \nRead more: https://www.icg.agency/blog/20-years-on-the-pitch-together/ about long standing partnership with LFE.\n \nCome on England!\n \n##UNSUB-LINE##', -1, 1784115345, 1784125988);
