olor: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email\'s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=\"bodyContentCenter\"] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span > a, span > a[href] {color: inherit !important;}\n  a > span, .ii a[href] > span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-200 img {\n    max-width: 200px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n        <tr>\n          <td>\n    <![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg\" style=\"display:inline-block;\" />\n						 <a href=\"https://www.icg.agency/\"><img src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" style=\"max-width:200px\" /></a> --></p>\n<div class=\"logo-wrap-200\" style=\"max-width: 200px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 200px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerTop\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h3>Hi ##CONTACT-FNAME##,</h3>\n<h2><strong>Celebrating another long-standing client partnership</strong></h2>\n<p>We are super proud of our 20-year partnership with League Football Education.</p>\n<p>In the last two decades we\'ve helped the charity shape how it communicates and connects with thousands of young apprentice footballers, their families, clubs and education providers across the country.</p>\n<p>What makes this partnership genuinely rewarding is seeing how LFE\'s apprentices progress through their careers - including Jude Bellingham, a former LFE apprentice.</p>\n<p><a href=\"https://www.icg.agency/blog/20-years-on-the-pitch-together/\">Read more</a> about long standing partnership with LFE.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\"><img src=\"https://portal.icg.agency/wp-content/uploads/2026/07/LFExICG_20years.jpg\" alt=\"LFE x ICG 20 years\" width=\"1000\" height=\"525\" /></td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"border-top: 1px solid #f0f0f0;\" valign=\"top\">\n<h2><strong>Fresh thinking from MAD//Fest London 2026</strong></h2>\n<p>In the fast moving world of marketing, we are always hungry for the latest industry insights.&nbsp;</p>\n<p>Last week two members of the team joined thousands of fellow marketers, brands and agencies at MAD//Fest London 2026, one of the UK\'s biggest marketing festivals.</p>\n<p><a href=\"https://www.icg.agency/blog/fresh-thinking-from-mad-fest-london-2026/\">Read more</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><strong>We are a BIBAS finalist</strong></h2>\n<p>ICG is pleased to have been shortlisted in the BIBAs - Lancashire\'s premier business awards.&nbsp;</p>\n<p>We are competing in the Creative, Digital &amp; Marketing Business of the Year category - see you at the awards ceremony on September 18 at the Blackpool Tower Ballroom.&nbsp;</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" valign=\"top\">\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"margin: 0; padding-top: 10px; line-height: 1; border-top: 1px solid #f0f0f0;\" align=\"left\" valign=\"top\">\n<p style=\"padding-top: 20px;\">ICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n<p><a href=\"https://www.icg.agency\">www.icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td valign=\"top\" width=\"100%\">\n<p style=\"text-align: center;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg\" style=\"margin:0 auto 0 auto;display:inline-block;\" />--></p>\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n<h6 style=\"text-align: center; margin-top: 9px;\">##BIZ-NAME##</h6>\n<h6 style=\"text-align: center;\">##BIZ-CONTACT##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">---</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n          </td>\n        </tr>\n    </table>\n    <![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hi ##CONTACT-FNAME##,\n \nCelebrating another long-standing client partnership\n \nWe are super proud of our 20-year partnership with League Football Education.\n \nIn the last two decades we\'ve helped the charity shape how it communicates and connects with thousands of young apprentice footballers, their families, clubs and education providers across the country.\n \nWhat makes this partnership genuinely rewarding is seeing how LFE\'s apprentices progress through their careers - including Jude Bellingham, a former LFE apprentice.\n \nRead more: https://www.icg.agency/blog/20-years-on-the-pitch-together/ about long standing partnership with LFE.\n \nFresh thinking from MAD//Fest London 2026\nIn the fast moving world of marketing, we are always hungry for the latest industry insights. \n\nLast week two members of the team joined thousands of fellow marketers, brands and agencies at MAD//Fest London 2026, one of the UK\'s biggest marketing festivals.\n\n\nWe are a BIBAS finalist\nICG is pleased to have been shortlisted in the BIBAs - Lancashire\'s premier business awards. \n\nWe are competing in the Creative, Digital & Marketing Business of the Year category - see you at the awards ceremony on September 18 at the Blackpool Tower Ballroom. \n\nICG is an integrated creative, digital and marketing agency, based in Preston. If you would like to discuss your marketing needs email simon@icg.agency\n\nwww.icg.agency\n\n\n##UNSUB-LINE##', -1, 1784126948, 1784188076);
INSERT INTO `1iPbG4KPq_zbs_mail` (`ID`, `zbs_site`, `zbs_team`, `zbs_owner`, `zbsmail_sender`, `zbsmail_subject`, `zbsmail_body`, `zbsmail_textbody`, `zbsmail_templateid`, `zbsmail_created`, `zbsmail_lastupdated`) VALUES
(32, 1, 1, 1, 'zbssmtp::noreply-portal-icg-agency', 'An exciting September ahead', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <title>##TITLE##</title>\n\n<style type=\"text/css\">\n  /* ///////// CLIENT-SPECIFIC STYLES ///////// */\n  #outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* ///////// RESET STYLES ///////// */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerTop {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email\'s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email\'s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=\"bodyContentCenter\"] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span > a, span > a[href] {color: inherit !important;}\n  a > span, .ii a[href] > span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-200 img {\n    max-width: 200px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n        <tr>\n          <td>\n    <![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg\" style=\"display:inline-block;\" />\n						 <a href=\"https://www.icg.agency/\"><img src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" style=\"max-width:200px\" /></a> --></p>\n<div class=\"logo-wrap-200\" style=\"max-width: 200px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/?utm_source=portal&amp;utm_medium=email&amp;utm_campaign=aug26\"><img style=\"max-width: 200px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerTop\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h3>Hi ##CONTACT-FNAME##,</h3>\n<h2><span style=\"font-weight: 900;\">An exciting September ahead</span></h2>\n<p><span style=\"font-weight: 400;\">As summer draws to a close, we have a vibrant and event-packed autumn ahead.</span></p>\n<p><span style=\"font-weight: 400;\">First up is the <a href=\"https://www.taforum.org/community/events/taf-annual-conference/\" target=\"_blank\" rel=\"noopener\">Trade Association Forum&rsquo;s Annual Conference</a> on September 10th where we will be connecting with delegates.</span></p>\n<p><span style=\"font-weight: 400;\">From London, we head to our Belfast office and the Northern Ireland Chamber of Commerce and Industry&rsquo;s <a href=\"https://www.northernirelandchamber.com/event/festival-of-business-2026/\" target=\"_blank\" rel=\"noopener\">Festival of Business 2026</a> on September 16th.</span></p>\n<p><span style=\"font-weight: 400;\">Team ICG will also be visiting the garden retail trade show, Glee 2026 and attending the <a href=\"https://www.thebibas.co.uk/\" target=\"_blank\" rel=\"noopener\">BIBAs</a> as a finalist in the Creative, Digital &amp; Marketing Business of the Year category at the iconic Blackpool Tower Ballroom.</span></p>\n<p><strong>Have a great bank holiday weekend - and we look forward to seeing you soon.</strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\"><a href=\"https://www.icg.agency/?utm_source=portal&amp;utm_medium=email&amp;utm_campaign=aug26\"><img src=\"https://portal.icg.agency/wp-content/uploads/2026/08/ICG-Email-Image_Aug-26-v2.jpg\" alt=\"ICG Email Image_Aug 26 v2\" width=\"1000\" height=\"400\" /></a><br /><br /></td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"border-top: 1px solid #f0f0f0;\" valign=\"top\">\n<h2><span style=\"font-weight: 900;\">Take Five with Sophie</span></h2>\n<p><span style=\"font-weight: 400;\">Meet Sophie, the newest addition to our marketing team, in our latest Take Five series.</span></p>\n<p><span style=\"font-weight: 400;\">Say hello to Sophie and discover her journey.</span></p>\n<p><a href=\"https://www.icg.agency/blog/take-five-with-sophie/?utm_source=portal&amp;utm_medium=email&amp;utm_campaign=aug26\" target=\"_blank\" rel=\"noopener\">Read more</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><span style=\"font-weight: 900;\">Cotswolds Designer Outlet - one year on</span></h2>\n<p><span style=\"font-weight: 400;\">It&rsquo;s been one year since our client, Cotswolds Designer Outlet, opened its doors.</span></p>\n<p><span style=\"font-weight: 400;\">Over the past 12 months, we have worked together to welcome millions of visitors and create countless memorable experiences.</span></p>\n<p><a href=\"https://www.icg.agency/blog/cotswolds-designer-outlet-one-year-on/?utm_source=portal&amp;utm_medium=email&amp;utm_campaign=aug26\" target=\"_blank\" rel=\"noopener\"><span style=\"font-weight: 400;\">Read more</span></a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" valign=\"top\">\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td align=\"left\" valign=\"top\">\n<p>ICG is an integrated creative, digital and marketing agency, based in Preston&nbsp;and Belfast. If you would like to discuss your marketing needs email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td valign=\"top\" width=\"100%\">\n<p style=\"text-align: center;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-03.jpg\" style=\"margin:0 auto 0 auto;display:inline-block;\" />--></p>\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/?utm_source=portal&amp;utm_medium=email&amp;utm_campaign=aug26\"><img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n<h6 style=\"text-align: center; margin-top: 9px;\">##BIZ-NAME##</h6>\n<h6 style=\"text-align: center;\">##BIZ-CONTACT##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">---</h6>\n<h6 style=\"text-align: center; margin-top: 7px;\">##POWERED-BY##</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n          </td>\n        </tr>\n    </table>\n    <![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hi ##CONTACT-FNAME##,\n \nAn exciting September ahead\n \nAs summer draws to a close, we have a vibrant and event-packed autumn ahead.\n \nFirst up is the Trade Association Forum’s Annual Conference on September 10th where we will be connecting with delegates.\n \nFrom London, we head to our Belfast office and the Northern Ireland Chamber of Commerce and Industry’s Festival of Business 2026: https://www.northernirelandchamber.com/event/festival-of-business-2026/ on September 16th.\n \nTeam ICG will also be visiting the garden retail trade show, Glee 2026 and attending the BIBAs: https://www.thebibas.co.uk/ as a finalist in the Creative, Digital & Marketing Business of the Year category at the iconic Blackpool Tower Ballroom.\n \nHave a great bank holiday weekend - and we look forward to seeing you soon.\n \nTake Five with Sophie\n \nMeet Sophie, the newest addition to our marketing team, in our latest Take Five series.\n \nSay hello to Sophie and discover her journey.\n \nRead more\n \nCotswolds Designer Outlet - one year on\n \nIt’s been one year since our client, Cotswolds Designer Outlet, opened its doors.\n \nOver the past 12 months, we have worked together to welcome millions of visitors and create countless memorable experiences.\n \nRead more\n \nICG is an integrated creative, digital and marketing agency, based in Preston and Belfast. If you would like to discuss your marketing needs email simon@icg.agency: mailto:simon@icg.agency\n \n##BIZ-NAME##\n \n##BIZ-CONTACT##\n \n##UNSUB-LINE##\n \n---\n \n##POWERED-BY##', -1, 1787733434, 1787835410),
(33, 1, 1, 1, 'zbssmtp::noreply-portal-icg-agency', 'ICG at Belfast’s iconic St George’s market', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Email Preview</title>\n\n<style type=\"text/css\">\n  /* ///////// CLIENT-SPECIFIC STYLES ///////// */\n  #outlook a { padding: 0; }\n  .ReadMsgBody { width: 100%; } \n  .ExternalClass { width: 100%; }\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div { line-height: 100%; }\n  body, table, td, p, a, li, blockquote { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; font-family: Helvetica, Arial, sans-serif; }\n  table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }\n  td ul li {\n    font-size: 16px;\n  }\n\n  /* ///////// RESET STYLES ///////// */\n  body { margin: 0; padding: 0; min-width: 100% !important; background-color: #ffffff; }\n  img {\n    max-width: 100%;\n    border: 0;\n    line-height: 100%;\n    outline: none;\n    text-decoration: none;\n  }\n  table { border-collapse: collapse !important; }\n  .content { width: 100%; max-width: 600px; }\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable { margin: 0; padding: 0; width: 100% !important; }\n  #bodyCell { margin: 0; padding: 0; }\n  #bodyCellFooter { margin: 0; padding: 0; width: 100% !important; padding-top: 39px; padding-bottom: 15px; }\n\n  #templateContainerHeader {\n    border-top: 1px solid #e2e2e2;\n    border-left: 1px solid #e2e2e2;\n    border-right: 1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top: 2.429em;\n    padding-bottom: 0.929em;\n  }\n  #templateContainerFootBrd {\n    border-bottom: 1px solid #e2e2e2;\n    border-left: 1px solid #e2e2e2;\