serif;\n    font-size: 14px;\n    line-height: 150%;\n    padding-top: 1.5em;\n    padding-right: 3.571em;\n    padding-left: 3.571em;\n    padding-bottom: 1.5em;\n    text-align: left;\n  }\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight: normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  .unSubContent {\n    font-family: Helvetica, Arial, sans-serif !important;\n  }\n  .unSubContent a:visited { color: #a1a1a1; text-decoration: underline; font-weight: normal; }\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration: underline; font-weight: normal; }\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration: underline; font-weight: normal; }\n  .unSubContent a:link    { color: #a1a1a1; text-decoration: underline; font-weight: normal; }\n  .unSubContent a .yshortcuts { color: #a1a1a1; text-decoration: underline; font-weight: normal; }\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-family: Helvetica, Arial, sans-serif !important;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .zbs-contact-detail {\n    font-family: Helvetica, Arial, sans-serif !important;\n    font-size: 12px;\n    line-height: 1.5em;\n    color: #a1a1a1;\n    text-align: center;\n  }\n  .zbs-contact-detail a {\n    color: #a1a1a1;\n    text-decoration: underline;\n    font-family: Helvetica, Arial, sans-serif !important;\n  }\n\n  a:visited { color: #3386e4; text-decoration: none; }\n  a:focus   { color: #3386e4; text-decoration: none; }\n  a:hover   { color: #3386e4; text-decoration: none; }\n  a:link    { color: #3386e4; text-decoration: none; }\n  a .yshortcuts { color: #3386e4; text-decoration: none; }\n\n  .bodyContent img {\n    height: auto;\n    max-width: 498px;\n  }\n\n  .footerContent {\n    color: #808080;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 10px;\n    line-height: 150%;\n    padding-top: 2.000em;\n    padding-right: 2.000em;\n    padding-bottom: 2.000em;\n    padding-left: 2.000em;\n    text-align: left;\n  }\n\n  .footerContent a:link, .footerContent a:visited, .footerContent a .yshortcuts, .footerContent a span {\n    color: #606060;\n    font-weight: normal;\n    text-decoration: underline;\n  }\n\n  #templateContainerImageFull { border-left: 1px solid #e2e2e2; border-right: 1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top: 1px solid #e2e2e2;\n    border-left: 1px solid #e2e2e2;\n    border-right: 1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n\n  .bodyContentImageFull p { font-size: 0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top: 10px solid #5098ea;\n    border-bottom: 10px solid #5098ea;\n    border-left: 20px solid #5098ea;\n    border-right: 20px solid #5098ea;\n    text-decoration: none;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide { display: none !important; }\n    body[yahoo] .buttonwrapper { background-color: transparent !important; }\n    body[yahoo] .button { padding: 0px !important; }\n    body[yahoo] .button a { background-color: #e05443; padding: 15px 15px 13px !important; }\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none !important; }\n  }\n\n  @media only screen and (max-width: 480px) {\n    h1 { font-size: 34px !important; }\n    h2 { font-size: 30px !important; }\n    h3 { font-size: 24px !important; }\n    h4 { font-size: 18px !important; }\n    h5 { font-size: 16px !important; }\n    h6 { font-size: 14px !important; }\n    p { font-size: 18px !important; }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent { padding: 6% 5% 1% 6% !important; }\n    .bodyContent img { max-width: 100% !important; }\n    .bodyContentImage { padding: 5% 6% 5% 6% !important; }\n    .bodyContentImage img { max-width: 100% !important; }\n    .bodyContentImage h4 { font-size: 16px !important; }\n    .bodyContentImage h5 { font-size: 15px !important; margin-top: 0; }\n    td[class=\"bodyContentCenter\"] { padding: 6% 6% 6% 6% !important; }\n  }\n\n  .ii a[href] { color: inherit !important; }\n  span > a, span > a[href] { color: inherit !important; }\n  a > span, .ii a[href] > span { text-decoration: inherit !important; }\n\n  .logo-wrap-200 img {\n    max-width: 200px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n<table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n<tr>\n<td>\n<![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0; font-family: Helvetica, Arial, sans-serif;\">&nbsp;</p>\n<div class=\"logo-wrap-200\" style=\"max-width: 200px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/?utm_source=portal&amp;utm_medium=email&amp;utm_campaign=aug26\"> <img style=\"max-width: 200px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /> </a></div>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerTop\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"font-family: Helvetica, Arial, sans-serif;\" valign=\"top\">\n<h3 style=\"font-family: Helvetica, Arial, sans-serif;\">Hi ##CONTACT-FNAME##,</h3>\n<h2 style=\"font-family: Helvetica, Arial, sans-serif;\"><span style=\"font-weight: 900;\">ICG at Belfast&rsquo;s iconic St George&rsquo;s market</span></h2>\n<p style=\"font-family: Helvetica, Arial, sans-serif;\"><span style=\"font-weight: 400;\">We were delighted to join businesses from across Northern Ireland for the Festival of Business 2026.</span></p>\n<p style=\"font-family: Helvetica, Arial, sans-serif;\"><span style=\"font-weight: 400;\">It was a great opportunity to chat with delegates and catch up with clients in the region including City of Derry Airport and the team at Designer Sofas\' Belfast store.</span></p>\n<p style=\"font-family: Helvetica, Arial, sans-serif;\"><span style=\"font-weight: 400;\">The event was held at St George&rsquo;s Market - one of Belfast&rsquo;s oldest attractions - so we fully embraced the market theme with ICG bunting and sweet-shop!</span></p>\n<p style=\"font-family: Helvetica, Arial, sans-serif;\"><span style=\"font-weight: 400;\">Organised by the NI Chamber of Commerce, Matthew, Dave and Simon talked all things marketing, sharing insights, experiences and a friendly hello.</span></p>\n<p style=\"font-family: Helvetica, Arial, sans-serif;\"><span style=\"font-weight: 400;\">As we start to grow our presence in the region, we are looking forward to getting involved in lots more events - watch this space.</span></p>\n<p style=\"font-family: Helvetica, Arial, sans-serif;\"><strong>Find out more about <a href=\"https://www.icg.agency/icg-belfast/\" target=\"_blank\" rel=\"noopener\">ICG Belfast</a></strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\"><img src=\"https://portal.icg.agency/wp-content/uploads/2026/09/ICG-Email-Image_Sept-26.jpg\" alt=\"ICG-Email-Image_Sept-26\" width=\"1000\" height=\"400\" /><br /><br /></td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"border-top: 1px solid #f0f0f0; font-family: Helvetica, Arial, sans-serif;\" valign=\"top\">\n<h2 style=\"font-family: Helvetica, Arial, sans-serif;\"><span style=\"font-weight: 900;\">Highly Commended at the BIBAs</span></h2>\n<p style=\"font-family: Helvetica, Arial, sans-serif;\"><span style=\"font-weight: 400;\">There&rsquo;s nowhere quite like the Blackpool Tower Ballroom&hellip;</span></p>\n<p style=\"font-family: Helvetica, Arial, sans-serif;\"><span style=\"font-weight: 400;\">We were delighted to be awarded a Highly Commended in the Creative, Digital &amp; Marketing Business of the Year category at the BIBAs - Lancashire\'s premier business awards, celebrating the county\'s top companies, entrepreneurs and world-class business community.</span></p>\n<p style=\"font-family: Helvetica, Arial, sans-serif;\"><a href=\"https://www.icg.agency/blog/highly-commended-at-lancashires-business-awards/\" target=\"_blank\" rel=\"noopener\">Read more</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" style=\"font-family: Helvetica, Arial, sans-serif;\" valign=\"top\">\n<h2 style=\"font-family: Helvetica, Arial, sans-serif;\"><span style=\"font-weight: 900;\">&lsquo;It&rsquo;s the most&hellip; busiest time of the year</span></h2>\n<p style=\"font-family: Helvetica, Arial, sans-serif;\"><span style=\"font-weight: 400;\">Preparations for the golden quarter are already well underway for our consumer facing clients&hellip;.think grottos, TV ads and festive social teasers.</span></p>\n<p style=\"font-family: Helvetica, Arial, sans-serif;\"><a href=\"https://www.icg.agency/blog/maximising-the-golden-quarter-for-retail/\" target=\"_blank\" rel=\"noopener\"><span style=\"font-weight: 400;\">Read more</span></a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" style=\"background-color: #f7f7f7;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" bgcolor=\"#f7f7f7\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" style=\"font-family: Helvetica, Arial, sans-serif; background-color: #f7f7f7;\" valign=\"top\" bgcolor=\"#f7f7f7\">\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"font-family: Helvetica, Arial, sans-serif;\" align=\"left\" valign=\"top\">\n<p style=\"font-family: Helvetica, Arial, sans-serif; margin-bottom: 0;\">ICG is an integrated creative, digital and marketing agency, with offices in Preston &amp; Belfast. If you would like to discuss your marketing needs, email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" style=\"font-family: Helvetica, Arial, sans-serif;\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"font-family: Helvetica, Arial, sans-serif;\" align=\"center\" valign=\"top\" width=\"100%\">\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/?utm_source=portal&amp;utm_medium=email&amp;utm_campaign=aug26\"> <img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /> </a></div>\n<h6 style=\"text-align: center; margin-top: 9px; margin-bottom: 0; font-family: Helvetica, Arial, sans-serif; font-size: 12px; color: #a1a1a1; font-weight: normal;\">ICG. Strategic Marketing Agency.</h6>\n<br />\n<div class=\"zbs-contact-detail\" style=\"font-family: Helvetica, Arial, sans-serif; font-size: 12px; line-height: 1.5em; color: #a1a1a1; text-align: center;\">Preston Office: Windy Harbour Barn, Harbour Lane, Warton, Preston PR4 1YB<br /><br /></div>\n<div class=\"zbs-contact-detail\" style=\"font-family: Helvetica, Arial, sans-serif; font-size: 12px; line-height: 1.5em; color: #a1a1a1; text-align: center;\">Belfast Office: River House, 48 60 High Street, Belfast BT1 2BE<br /><br /></div>\n<div class=\"zbs-contact-detail\" style=\"font-family: Helvetica, Arial, sans-serif; font-size: 12px; line-height: 1.5em; color: #a1a1a1; text-align: center;\"><a style=\"color: #a1a1a1; text-decoration: underline; font-family: Helvetica, Arial, sans-serif;\" href=\"https://www.icg.agency/\">icg.agency</a></div>\n<div class=\"zbs-contact-detail\" style=\"font-family: Helvetica, Arial, sans-serif; font-size: 12px; line-height: 1.5em; color: #a1a1a1; text-align: center;\">&nbsp;</div>\n<h6 style=\"text-align: center; margin-top: 7px; margin-bottom: 0; font-family: Helvetica, Arial, sans-serif; font-size: 12px; color: #a1a1a1;\">&nbsp;##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px; margin-bottom: 0; font-family: Helvetica, Arial, sans-serif; font-size: 12px; color: #a1a1a1;\">---</h6>\n<h6 style=\"text-align: center; margin-top: 7px; margin-bottom: 0; font-family: Helvetica, Arial, sans-serif; font-size: 12px; color: #a1a1a1;\">&nbsp;</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n</td>\n</tr>\n</table>\n<![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hi ##CONTACT-FNAME##,\n \nICG at Belfast’s iconic St George’s market\n \nWe were delighted to join businesses from across Northern Ireland for the Festival of Business 2026.\n \nIt was a great opportunity to chat with delegates and catch up with clients in the region including City of Derry Airport and the team at Designer Sofas\' Belfast store.\n \nThe event was held at St George’s Market - one of Belfast’s oldest attractions - so we fully embraced the market theme with ICG bunting and sweet-shop!\n \nOrganised by the NI Chamber of Commerce, Matthew, Dave and Simon talked all things marketing, sharing insights, experiences and a friendly hello.\n \nAs we start to grow our presence in the region, we are looking forward to getting involved in lots more events - watch this space.\n \nFind out more about ICG Belfast: https://www.icg.agency/icg-belfast/\n \nHighly Commended at the BIBAs\n \nThere’s nowhere quite like the Blackpool Tower Ballroom…\n \nWe were delighted to be awarded a Highly Commended in the Creative, Digital & Marketing Business of the Year category at the BIBAs - Lancashire\'s premier business awards, celebrating the county\'s top companies, entrepreneurs and world-class business community.\n \nRead more: https://www.icg.agency/blog/highly-commended-at-lancashires-business-awards/\n \n‘It’s the most… busiest time of the year\n \nPreparations for the golden quarter are already well underway for our consumer facing clients….think grottos, TV ads and festive social teasers.\n \nRead more: https://www.icg.agency/blog/maximising-the-golden-quarter-for-retail/\n \nICG is an integrated creative, digital and marketing agency, with offices in Preston & Belfast. If you would like to discuss your marketing needs, email simon@icg.agency: mailto:simon@icg.agency\n \nICG. Strategic Marketing Agency.\n \nPreston Office: Windy Harbour Barn, Harbour Lane, Warton, Preston PR4 1YB\n \nBelfast Office: River House, 48 60 High Street, Belfast BT1 2BE\n \nicg.agency: https://www.icg.agency/\n \n ##UNSUB-LINE##\n \n---', -1, 1790327879, 1790341952);
INSERT INTO `1iPbG4KPq_zbs_mail` (`ID`, `zbs_site`, `zbs_team`, `zbs_owner`, `zbsmail_sender`, `zbsmail_subject`, `zbsmail_body`, `zbsmail_textbody`, `zbsmail_templateid`, `zbsmail_created`, `zbsmail_lastupdated`) VALUES
(34, 1, 1, 6, 'zbssmtp::noreply-portal-icg-agency', 'A rebrand for BUMAX', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>##TITLE##</title>\n\n<style type=\"text/css\">\n  /* ///////// CLIENT-SPECIFIC STYLES ///////// */\n  #outlook a { padding: 0; }\n  .ReadMsgBody { width: 100%; } \n  .ExternalClass { width: 100%; }\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div { line-height: 100%; }\n  body, table, td, p, a, li, blockquote { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; font-family: Helvetica, Arial, sans-serif; }\n  table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }\n  td ul li {\n    font-size: 16px;\n  }\n\n  /* ///////// RESET STYLES ///////// */\n  body { margin: 0; padding: 0; min-width: 100% !important; background-color: #ffffff; }\n  img {\n    max-width: 100%;\n    border: 0;\n    line-height: 100%;\n    outline: none;\n    text-decoration: none;\n  }\n  table { border-collapse: collapse !important; }\n  .content { width: 100%; max-width: 600px; }\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable { margin: 0; padding: 0; width: 100% !important; }\n  #bodyCell { margin: 0; padding: 0; }\n  #bodyCellFooter { margin: 0; padding: 0; width: 100% !important; padding-top: 39px; padding-bottom: 15px; }\n\n  #templateContainerHeader {\n    border-top: 1px solid #e2e2e2;\n    border-left: 1px solid #e2e2e2;\n    border-right: 1px solid #e2e2e2;\n    font-size: 14px;\n    padding-top: 2.429em;\n    padding-bottom: 0.929em;\n  }\n  #templateContainerFootBrd {\n    border-bottom: 1px solid #e2e2e2;\n    border-left: 1px solid #e2e2e2;\n    border-right: 1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width: 100% !important;\n  }\n  #templateContainer {\n    border-top: 1px solid #e2e2e2;\n    border-left: 1px solid #e2e2e2;\n    border-right: 1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerMiddle {\n    border-left: 1px solid #e2e2e2;\n    border-right: 1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left: 1px solid #e2e2e2;\n    border-right: 1px solid #e2e2e2;\n    border-bottom: 1px solid #e2e2e2;\n    background-color: #f7f7f7;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  h1 {\n    color: #2e2e2e;\n    display: block;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 26px;\n    line-height: 1.385em;\n    font-style: normal;\n    font-weight: normal;\n    letter-spacing: normal;\n    margin-top: 0;\n    margin-right: 0;\n    margin-bottom: 15px;\n    margin-left: 0;\n    text-align: left;\n  }\n\n  h2 {\n    color: #2e2e2e;\n    display: block;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 22px;\n    line-height: 1.455em;\n    font-style: normal;\n    font-weight: normal;\n    letter-spacing: normal;\n    margin-top: 0;\n    margin-right: 0;\n    margin-bottom: 15px;\n    margin-left: 0;\n    text-align: left;\n  }\n\n  h3 {\n    color: #545454;\n    display: block;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 18px;\n    line-height: 1.444em;\n    font-style: normal;\n    font-weight: normal;\n    letter-spacing: normal;\n    margin-top: 0;\n    margin-right: 0;\n    margin-bottom: 15px;\n    margin-left: 0;\n    text-align: left;\n  }\n\n  h4 {\n    color: #545454;\n    display: block;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 14px;\n    line-height: 1.571em;\n    font-style: normal;\n    font-weight: normal;\n    letter-spacing: normal;\n    margin-top: 0;\n    margin-right: 0;\n    margin-bottom: 15px;\n    margin-left: 0;\n    text-align: left;\n  }\n\n  h5 {\n    color: #545454;\n    display: block;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 13px;\n    line-height: 1.538em;\n    font-style: normal;\n    font-weight: normal;\n    letter-spacing: normal;\n    margin-top: 0;\n    margin-right: 0;\n    margin-bottom: 15px;\n    margin-left: 0;\n    text-align: left;\n  }\n\n  h6 {\n    color: #545454;\n    display: block;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 12px;\n    line-height: 2.000em;\n    font-style: normal;\n    font-weight: normal;\n    letter-spacing: normal;\n    margin-top: 0;\n    margin-right: 0;\n    margin-bottom: 15px;\n    margin-left: 0;\n    text-align: left;\n  }\n\n  p {\n    color: #545454;\n    display: block;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 16px;\n    line-height: 1.500em;\n    font-style: normal;\n    font-weight: normal;\n    letter-spacing: normal;\n    margin-top: 0;\n    margin-right: 0;\n    margin-bottom: 15px;\n    margin-left: 0;\n    text-align: left;\n  }\n\n  .bodyContent {\n    color: #505050;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 14px;\n    line-height: 150%;\n    padding-top: 3.143em;\n    padding-right: 3.5em;\n    padding-left: 3.5em;\n    padding-bottom: 0.714em;\n    text-align: left;\n  }\n  .bodyContentCenter {\n    color: #505050;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 14px;\n    line-height: 150%;\n    padding-top: 0em;\n    padding-right: 3.5em;\n    padding-left: 3.5em;\n    padding-bottom: 3.0em;\n    text-align: center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color: #505050;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 14px;\n    line-height: 150%;\n    padding-top: 1.5em;\n    padding-right: 3.571em;\n    padding-left: 3.571em;\n    padding-bottom: 1.5em;\n    text-align: left;\n  }\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight: normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  .unSubContent {\n    font-family: Helvetica, Arial, sans-serif !important;\n  }\n  .unSubContent a:visited { color: #a1a1a1; text-decoration: underline; font-weight: normal; }\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration: underline; font-weight: normal; }\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration: underline; font-weight: normal; }\n  .unSubContent a:link    { color: #a1a1a1; text-decoration: underline; font-weight: normal; }\n  .unSubContent a .yshortcuts { color: #a1a1a1; text-decoration: underline; font-weight: normal; }\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-family: Helvetica, Arial, sans-serif !important;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  /* Specific footer styling for office addresses */\n  .zbs-contact-detail {\n    font-family: Helvetica, Arial, sans-serif !important;\n    font-size: 12px;\n    line-height: 1.5em;\n    color: #a1a1a1;\n    text-align: center;\n  }\n  .zbs-contact-detail a {\n    color: #a1a1a1;\n    text-decoration: underline;\n    font-family: Helvetica, Arial, sans-serif !important;\n  }\n\n  a:visited { color: #3386e4; text-decoration: none; }\n  a:focus   { color: #3386e4; text-decoration: none; }\n  a:hover   { color: #3386e4; text-decoration: none; }\n  a:link    { color: #3386e4; text-decoration: none; }\n  a .yshortcuts { color: #3386e4; text-decoration: none; }\n\n  .bodyContent img {\n    height: auto;\n    max-width: 498px;\n  }\n\n  .footerContent {\n    color: #808080;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 10px;\n    line-height: 150%;\n    padding-top: 2.000em;\n    padding-right: 2.000em;\n    padding-bottom: 2.000em;\n    padding-left: 2.000em;\n    text-align: left;\n  }\n\n  .footerContent a:link, .footerContent a:visited, .footerContent a .yshortcuts, .footerContent a span {\n    color: #606060;\n    font-weight: normal;\n    text-decoration: underline;\n  }\n\n  #templateContainerImageFull { border-left: 1px solid #e2e2e2; border-right: 1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top: 1px solid #e2e2e2;\n    border-left: 1px solid #e2e2e2;\n    border-right: 1px solid #e2e2e2;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    background-clip: padding-box;\n  }\n\n  .bodyContentImageFull p { font-size: 0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top: 10px solid #5098ea;\n    border-bottom: 10px solid #5098ea;\n    border-left: 20px solid #5098ea;\n    border-right: 20px solid #5098ea;\n    text-decoration: none;\n    font-family: Helvetica, Arial, sans-serif;\n    font-size: 14px;\n    margin-top: 1.0em;\n    background-clip: padding-box;\n  }\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide { display: none !important; }\n    body[yahoo] .buttonwrapper { background-color: transparent !important; }\n    body[yahoo] .button { padding: 0px !important; }\n    body[yahoo] .button a { background-color: #e05443; padding: 15px 15px 13px !important; }\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; text-decoration: none !important; }\n  }\n\n  @media only screen and (max-width: 480px) {\n    h1 { font-size: 34px !important; }\n    h2 { font-size: 30px !important; }\n    h3 { font-size: 24px !important; }\n    h4 { font-size: 18px !important; }\n    h5 { font-size: 16px !important; }\n    h6 { font-size: 14px !important; }\n    p { font-size: 18px !important; }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent { padding: 6% 5% 1% 6% !important; }\n    .bodyContent img { max-width: 100% !important; }\n    .bodyContentImage { padding: 5% 6% 5% 6% !important; }\n    .bodyContentImage img { max-width: 100% !important; }\n    .bodyContentImage h4 { font-size: 16px !important; }\n    .bodyContentImage h5 { font-size: 15px !important; margin-top: 0; }\n    td[class=\"bodyContentCenter\"] { padding: 6% 6% 6% 6% !important; }\n  }\n\n  .ii a[href] { color: inherit !important; }\n  span > a, span > a[href] { color: inherit !important; }\n  a > span, .ii a[href] > span { text-decoration: inherit !important; }\n\n  .logo-wrap-100 img {\n    max-width: 100px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n</style>\n</head>\n\n<body yahoo bgcolor=\"#ffffff\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"10\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td><!-- [if (gte mso 9)|(IE)]>\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n        <tr>\n          <td>\n    <![endif]-->\n<table class=\"content\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\" bgcolor=\"#ffffff\">\n<tbody>\n<tr>\n<td id=\"templateContainerHeader\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><!--<img src=\"http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg\" style=\"display:inline-block;\" />\n             <a href=\"https://www.icg.agency/\"><img src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" style=\"max-width:100px\" /></a> --></p>\n<div class=\"logo-wrap-100\" style=\"max-width: 100px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"><img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /></a></div>\n</td>\n</tr>\n<!-- Section 1: Bumax Story -->\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainer\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h3>Hello ##CONTACT-FNAME##</h3>\n<p>We\'re pleased to bring you our latest news, from bake sales to the Big Marketing Meet Up.</p>\n<h2><strong>A rebrand for BUMAX</strong></h2>\n<p>We were delighted to celebrate the launch of an exciting new brand identity for BUMAX, the Swedish manufacturer of high-performance stainless steel bolts engineered for the world&rsquo;s most demanding applications.</p>\n<p>ICG worked in partnership with BUMAX to deliver a new corporate identity, website and marketing materials, alongside a campaign marking the company&rsquo;s 100th anniversary.</p>\n<p>The project drew on ICG&rsquo;s teams across design, digital and content. We look forward to supporting BUMAX through its next 100 years, including the opening of its new factory in 2027.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<!-- Section 1 Button: Left-Aligned Neon Pill Button without Arrow -->\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContentCenter\" style=\"text-align: left;\" align=\"left\" valign=\"top\">\n<table style=\"margin: 0;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"left\">\n<tbody>\n<tr>\n<td style=\"border-radius: 50px; background-color: #d5ff67;\" align=\"center\" bgcolor=\"#d5ff67\"><a class=\"blue-btn\" style=\"background-color: #d5ff67 !important; border: 1px solid #d5ff67 !important; color: #000000 !important; font-family: Helvetica, Arial, sans-serif; font-size: 14px; font-weight: bold; text-decoration: none !important; text-transform: uppercase; letter-spacing: 0.5px; padding: 12px 28px; border-radius: 50px; display: inline-block;\" href=\"https://www.icg.agency/work/bumax/\" target=\"_blank\" rel=\"noopener\"> Read more </a></td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<!-- Repositioned Full-Width Image -->\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerImageFull\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContentImageFull\" valign=\"top\">\n<p style=\"text-align: center; margin: 0; padding: 0;\"><img style=\"display: block; width: 100%; max-width: 600px; height: auto;\" src=\"https://portal.icg.agency/wp-content/uploads/2026/10/ICG-Email-Image_OCT26.jpg\" alt=\"ICG Email Image\" /></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<!-- Section 2: Will we see you there? -->\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><strong>Will we see you there?</strong></h2>\n<p>We&rsquo;re hitting the road for two major marketing events next month.</p>\n<p>Matt and Julie are heading to the <a href=\"https://www.bmmubelfast.com/\">Big Marketing Meet Up (BMMU)</a> at the ICC international convention centre in Belfast on November 5th.</p>\n<p>It&rsquo;s set to be an action-packed day of inspiring conversations and fresh marketing insights. Be sure to stop by our stand!</p>\n<p>Then, we&rsquo;re off to Manchester on November 18th to exhibit at <a href=\"https://www.prolificnorth.co.uk/prolific-north-live/\">Prolific North Live</a> at Sister.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<!-- Section 3: Pumpkins and bakes at the barn -->\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddle\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td class=\"bodyContent\" valign=\"top\">\n<h2><strong>Pumpkins and bakes at the barn</strong></h2>\n<p>What\'s our favourite way to raise money for a fantastic cause? A bake sale, of course!</p>\n<p>Our team went all out with warm homemade goodies to support Breast Cancer Now for Breast Cancer Awareness Month.</p>\n<p>And in the spirit of Halloween we&rsquo;re also lighting up the barn this week with our scary pumpkin carving.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<!-- Agency Callout Box at Bottom of Card -->\n<tr>\n<td align=\"center\" valign=\"top\">\n<table id=\"templateContainerMiddleBtm\" style=\"background-color: #f7f7f7;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" bgcolor=\"#f7f7f7\">\n<tbody>\n<tr align=\"top\">\n<td class=\"bodyContentImage\" style=\"font-family: Helvetica, Arial, sans-serif; background-color: #f7f7f7; padding-top: 1.5em; padding-bottom: 1.5em;\" valign=\"top\" bgcolor=\"#f7f7f7\">\n<table border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"font-family: Helvetica, Arial, sans-serif;\" align=\"left\" valign=\"top\">\n<p style=\"font-family: Helvetica, Arial, sans-serif; margin-bottom: 0;\">ICG is a strategic marketing agency with offices in Preston and Belfast. If you would like to discuss your marketing needs, email <a href=\"mailto:simon@icg.agency\">simon@icg.agency</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n<!-- Footer: Full Two-Office Addresses & Agency Details -->\n<tr>\n<td id=\"bodyCellFooter\" class=\"unSubContent\" style=\"font-family: Helvetica, Arial, sans-serif;\" align=\"center\" valign=\"top\">\n<table id=\"templateContainerFooter\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"font-family: Helvetica, Arial, sans-serif;\" align=\"center\" valign=\"top\" width=\"100%\">\n<div class=\"logo-wrap\" style=\"max-width: 60px; margin-left: auto; margin-right: auto;\"><a href=\"https://www.icg.agency/\"> <img style=\"max-width: 100px;\" src=\"https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg\" alt=\"ICG\" /> </a></div>\n<h6 style=\"text-align: center; margin-top: 9px; margin-bottom: 0; font-family: Helvetica, Arial, sans-serif; font-size: 12px; color: #a1a1a1; font-weight: normal;\">ICG. Strategic Marketing Agency.</h6>\n<br />\n<div class=\"zbs-contact-detail\" style=\"font-family: Helvetica, Arial, sans-serif; font-size: 12px; line-height: 1.5em; color: #a1a1a1; text-align: center;\">Preston Office: Windy Harbour Barn, Harbour Lane, Warton, Preston PR4 1YB<br /><br /></div>\n<div class=\"zbs-contact-detail\" style=\"font-family: Helvetica, Arial, sans-serif; font-size: 12px; line-height: 1.5em; color: #a1a1a1; text-align: center;\">Belfast Office: River House, 48 60 High Street, Belfast BT1 2BE<br /><br /></div>\n<div class=\"zbs-contact-detail\" style=\"font-family: Helvetica, Arial, sans-serif; font-size: 12px; line-height: 1.5em; color: #a1a1a1; text-align: center;\"><a style=\"color: #a1a1a1; text-decoration: underline; font-family: Helvetica, Arial, sans-serif;\" href=\"https://www.icg.agency/\">icg.agency</a></div>\n<div class=\"zbs-contact-detail\" style=\"font-family: Helvetica, Arial, sans-serif; font-size: 12px; line-height: 1.5em; color: #a1a1a1; text-align: center;\">&nbsp;</div>\n<h6 style=\"text-align: center; margin-top: 7px; margin-bottom: 0; font-family: Helvetica, Arial, sans-serif; font-size: 12px; color: #a1a1a1;\">&nbsp;Click to unsubscribe: ##UNSUB-LINE##</h6>\n<h6 style=\"text-align: center; margin-top: 7px; margin-bottom: 0; font-family: Helvetica, Arial, sans-serif; font-size: 12px; color: #a1a1a1;\">---</h6>\n<h6 style=\"text-align: center; margin-top: 7px; margin-bottom: 0; font-family: Helvetica, Arial, sans-serif; font-size: 12px; color: #a1a1a1;\">&nbsp;</h6>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n</tr>\n</tbody>\n</table>\n<!-- [if (gte mso 9)|(IE)]>\n          </td>\n        </tr>\n    </table>\n    <![endif]--></td>\n</tr>\n</tbody>\n</table>\n</body>\n</html>', 'Hello ##CONTACT-FNAME##\n \nWe\'re pleased to bring you our latest news, from bake sales to the Big Marketing Meet Up.\n \nA rebrand for BUMAX\n \nWe were delighted to celebrate the launch of an exciting new brand identity for BUMAX, the Swedish manufacturer of high-performance stainless steel bolts engineered for the world’s most demanding applications.\n \nICG worked in partnership with BUMAX to deliver a new corporate identity, website and marketing materials, alongside a campaign marking the company’s 100th anniversary.\n \nThe project drew on ICG’s teams across design, digital and content. We look forward to supporting BUMAX through its next 100 years, including the opening of its new factory in 2027.\n \n Read more : https://www.icg.agency/work/bumax/\n \nWill we see you there?\n \nWe’re hitting the road for two major marketing events next month.\n \nMatt and Julie are heading to the Big Marketing Meet Up (BMMU) at the ICC international convention centre in Belfast on November 5th.\n \nIt’s set to be an action-packed day of inspiring conversations and fresh marketing insights. Be sure to stop by our stand!\n \nThen, we’re off to Manchester on November 18th to exhibit at Prolific North Live: https://www.prolificnorth.co.uk/prolific-north-live/ at Sister.\n \nPumpkins and bakes at the barn\n \nWhat\'s our favourite way to raise money for a fantastic cause? A bake sale, of course!\n \nOur team went all out with warm homemade goodies to support Breast Cancer Now for Breast Cancer Awareness Month.\n \nAnd in the spirit of Halloween we’re also lighting up the barn this week with our scary pumpkin carving.\n \nICG is a strategic marketing agency with offices in Preston and Belfast. If you would like to discuss your marketing needs, email simon@icg.agency: mailto:simon@icg.agency\n \nICG. Strategic Marketing Agency.\n \nPreston Office: Windy Harbour Barn, Harbour Lane, Warton, Preston PR4 1YB\n \nBelfast Office: River House, 48 60 High Street, Belfast BT1 2BE\n \nicg.agency: https://www.icg.agency/\n \n Click to unsubscribe: ##UNSUB-LINE##\n \n---', -1, 1793115058, 1793195642),
(35, 1, 1, 6, 'zbssmtp::noreply-portal-icg-agency', 'temp', '&lt;!DOCTYPE html PUBLIC &quot;-//W3C//DTD XHTML 1.0 Transitional//EN&quot; &quot;http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd&quot;&gt;\n&lt;html xmlns=&quot;http://www.w3.org/1999/xhtml&quot;&gt;\n&lt;head&gt;\n  &lt;meta http-equiv=&quot;Content-Type&quot; content=&quot;text/html; charset=utf-8&quot; /&gt;\n  &lt;title&gt;##TITLE##&lt;/title&gt;\n\n&lt;style type=&quot;text/css&quot;&gt;\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ CLIENT-SPECIFIC STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  #outlook a{padding:0;} /* Force Outlook to provide a &quot;view in browser&quot; message */\n  .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\n  .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */\n  body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */\n  table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */\n  td ul li {\n    font-size: 16px;\n  }\n  /* /\\/\\/\\/\\/\\/\\/\\/\\/ RESET STYLES /\\/\\/\\/\\/\\/\\/\\/\\/ */\n  body{margin:0; padding:0;}\n  img{\n    max-width:100%;\n    border:0;\n    line-height:100%;\n    outline:none;\n    text-decoration:none;\n  }\n  table{border-collapse:collapse !important;}\n  .content {width: 100%; max-width: 600px;}\n  .content img { height: auto; min-height: 1px; }\n\n  #bodyTable{margin:0; padding:0; width:100% !important;}\n  #bodyCell{margin:0; padding:0;}\n  #bodyCellFooter{margin:0; padding:0; width:100% !important;padding-top:39px;padding-bottom:15px;}\n  body {margin: 0; padding: 0; min-width: 100%!important;}\n\n  #templateContainerHeader{\n    font-size: 14px;\n    padding-top:2.429em;\n    padding-bottom:0.929em;\n  }\n  #templateContainerFootBrd{\n    border-bottom:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-radius: 0 0 4px 4px;\n    background-clip: padding-box;\n    border-spacing: 0;\n    height: 10px;\n    width:100% !important;\n  }\n  #templateContainer{\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-radius: 4px 4px 0 0 ;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n  #templateContainerMiddle {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n  }\n  #templateContainerMiddleBtm {\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-bottom:1px solid #e2e2e2;\n    border-radius: 0 0 4px 4px;\n    background-clip: padding-box;\n    border-spacing: 0;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 1\n  * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.\n  * @style heading 1\n  */\n  h1{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:26px;\n     line-height:1.385em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 2\n  * @tip Set the styling for all second-level headings in your emails.\n  * @style heading 2\n  */\n  h2{\n     color:#2e2e2e;\n    display:block;\n     font-family:Helvetica;\n     font-size:22px;\n     line-height:1.455em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 3\n  * @tip Set the styling for all third-level headings in your emails.\n  * @style heading 3\n  */\n  h3{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:18px;\n     line-height:1.444em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  /**\n  * @tab Page\n  * @section heading 4\n  * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.\n  * @style heading 4\n  */\n  h4{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:14px;\n     line-height:1.571em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h5{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:13px;\n     line-height:1.538em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n\n  h6{\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:12px;\n     line-height:2.000em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n     text-align:left;\n  }\n\n  p {\n     color:#545454;\n    display:block;\n     font-family:Helvetica;\n     font-size:16px;\n     line-height:1.500em;\n     font-style:normal;\n     font-weight:normal;\n     letter-spacing:normal;\n    margin-top:0;\n    margin-right:0;\n    margin-bottom:15px;\n    margin-left:0;\n    text-align:left;\n  }\n\n  .unSubContent a:visited { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:focus   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:hover   { color: #a1a1a1; text-decoration:underline; font-weight:normal;}\n  .unSubContent a:link   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n  .unSubContent a .yshortcuts   { color: #a1a1a1 ; text-decoration:underline; font-weight:normal;}\n\n  .unSubContent h6 {\n    color: #a1a1a1;\n    font-size: 12px;\n    line-height: 1.5em;\n    margin-bottom: 0;\n  }\n\n  .bodyContent{\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:3.143em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:0.714em;\n     text-align:left;\n  }\n  .bodyContentCenter {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0em;\n    padding-right:3.5em;\n    padding-left:3.5em;\n    padding-bottom:3.0em;\n    text-align:center;\n  }\n  .bodyContentCenter p {\n    margin-bottom: 0;\n    text-align: center;\n  }\n  .bodyContentCenter a.blue-btn {\n    margin-top: 0;\n  }\n  .bodyContentImage {\n    color:#505050;\n    font-family:Helvetica;\n    font-size:14px;\n    line-height:150%;\n    padding-top:0;\n    padding-right:3.571em;\n    padding-left:3.571em;\n    padding-bottom:2em;\n    text-align:left;\n  }\n\n  .bodyContentImage h4 {\n    color: #4E4E4E;\n    font-size: 13px;\n    line-height: 1.154em;\n    font-weight:normal;\n    margin-bottom: 0;\n  }\n  .bodyContentImage h5 {\n    color: #828282;\n    font-size: 12px;\n    line-height: 1.667em;\n    margin-bottom: 0;\n  }\n\n  /**\n  * @tab Body\n  * @section body link\n  * @tip Set the styling for your email&#039;s main content links. Choose a color that helps them stand out from your text.\n  */\n  a:visited { color: #3386e4; text-decoration:none;}\n  a:focus   { color: #3386e4; text-decoration:none;}\n  a:hover   { color: #3386e4; text-decoration:none;}\n  a:link   { color: #3386e4 ; text-decoration:none;}\n  a .yshortcuts   { color: #3386e4 ; text-decoration:none;}\n\n  .bodyContent img{\n    height:auto;\n    max-width:498px;\n  }\n\n  .footerContent{\n    color:#808080;\n    font-family:Helvetica;\n    font-size:10px;\n    line-height:150%;\n    padding-top:2.000em;\n    padding-right:2.000em;\n    padding-bottom:2.000em;\n    padding-left:2.000em;\n    text-align:left;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email&#039;s footer links. Choose a color that helps them stand out from your text.\n  */\n  .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{\n     color:#606060;\n     font-weight:normal;\n     text-decoration:underline;\n  }\n\n  /**\n  * @tab Footer\n  * @section footer link\n  * @tip Set the styling for your email&#039;s footer links. Choose a color that helps them stand out from your text.\n  */\n  #templateContainerImageFull { border-left:1px solid #e2e2e2; border-right:1px solid #e2e2e2; }\n  #templateContainerImageCurve {\n    border-top:1px solid #e2e2e2;\n    border-left:1px solid #e2e2e2;\n    border-right:1px solid #e2e2e2;\n    border-radius: 3px 3px 0px 0px;\n    background-clip: padding-box;\n    border-collapse: separate !important;\n    border-spacing: 0;\n  }\n  #templateContainerImageCurve img {\n    border-radius: 3px 3px 0px 0px;\n    background-clip: padding-box;\n  }\n  /*boom*/\n  .bodyContentImageFull p { font-size:0 !important; margin-bottom: 0 !important; }\n  .brdBottomPadd { border-bottom: 1px solid #f0f0f0; }\n  .brdBottomPadd .bodyContent { padding-bottom: 2.286em; }\n  a.blue-btn {\n    background: #5098ea;\n    display: inline-block;\n    color: #FFFFFF;\n    border-top:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-bottom:10px solid #5098ea;\n    border-left:20px solid #5098ea;\n    border-right:20px solid #5098ea;\n    text-decoration: none;\n    font-size: 14px;\n    margin-top: 1.0em;\n    border-radius: 3px 3px 3px 3px;\n    background-clip: padding-box;\n  }\n\n\n  @media only screen and (max-width: 550px), screen and (max-device-width: 550px) {\n    body[yahoo] .hide {display: none!important;}\n    body[yahoo] .buttonwrapper {background-color: transparent!important;}\n    body[yahoo] .button {padding: 0px!important;}\n    body[yahoo] .button a {background-color: #e05443; padding: 15px 15px 13px!important;}\n    body[yahoo] .unsubscribe { font-size: 14px; display: block; margin-top: 0.714em; padding: 10px 50px; background: #2f3942; border-radius: 5px; text-decoration: none!important;}\n  }\n  /*@media only screen and (min-device-width: 601px) {\n    .content {width: 600px !important;}\n  }*/\n  @media only screen and (max-width: 480px) {\n    h1 {\n      font-size:34px !important;\n    }\n    h2{\n      font-size:30px !important;\n    }\n    h3{\n      font-size:24px !important;\n    }\n    h4{\n      font-size:18px !important;\n    }\n    h5{\n      font-size:16px !important;\n    }\n    h6{\n      font-size:14px !important;\n    }\n    p {\n      font-size: 18px !important;\n    }\n    .brdBottomPadd .bodyContent { padding-bottom: 2.286em !important; }\n    .bodyContent {\n      padding: 6% 5% 1% 6% !important;\n    }\n    .bodyContent img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage {\n      padding: 3% 6% 6% 6% !important;\n    }\n    .bodyContentImage img {\n      max-width: 100% !important;\n    }\n    .bodyContentImage h4 {\n      font-size: 16px !important;\n    }\n    .bodyContentImage h5 {\n      font-size: 15px !important;\n      margin-top:0;\n    }\n    td[class=&quot;bodyContentCenter&quot;] {\n      padding: 6% 6% 6% 6% !important;\n    }\n  }\n  .ii a[href] {color: inherit !important;}\n  span &gt; a, span &gt; a[href] {color: inherit !important;}\n  a &gt; span, .ii a[href] &gt; span {text-decoration: inherit !important;}\n\n  /* WH additions */\n  .logo-wrap-100 img {\n    max-width: 100px !important; margin-left: auto; margin-right: auto;\n  }\n  .logo-wrap img {\n    max-width: 60px !important; margin-left: auto; margin-right: auto;\n  }\n&lt;/style&gt;\n&lt;/head&gt;\n\n&lt;body yahoo bgcolor=&quot;#ffffff&quot;&gt;\n&lt;table border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpadding=&quot;10&quot; bgcolor=&quot;#ffffff&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td&gt;&lt;!-- [if (gte mso 9)|(IE)]&gt;\n      &lt;table width=&quot;600&quot; align=&quot;center&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; border=&quot;0&quot;&gt;\n        &lt;tr&gt;\n          &lt;td&gt;\n    &lt;![endif]--&gt;\n&lt;table class=&quot;content&quot; border=&quot;0&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot; align=&quot;center&quot; bgcolor=&quot;#ffffff&quot;&gt;\n&lt;tbody&gt;\n&lt;tr&gt;\n&lt;td id=&quot;templateContainerHeader&quot; valign=&quot;top&quot;&gt;\n&lt;p style=&quot;text-align: center; margin: 0; padding: 0;&quot;&gt;&lt;!--&lt;img src=&quot;http://c0185784a2b233b0db9b-d0e5e4adc266f8aacd2ff78abb166d77.r51.cf2.rackcdn.com/templates/cog-01.jpg&quot; style=&quot;display:inline-block;&quot; /&gt;\n						 &lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; style=&quot;max-width:100px&quot; /&gt;&lt;/a&gt; --&gt;&lt;/p&gt;\n&lt;div class=&quot;logo-wrap-100&quot; style=&quot;max-width: 100px; margin-left: auto; margin-right: auto;&quot;&gt;&lt;a href=&quot;https://www.icg.agency/&quot;&gt;&lt;img style=&quot;max-width: 100px;&quot; src=&quot;https://portal.icg.agency/wp-content/uploads/2025/12/ICG_2020_logo_landscape.svg&quot; alt=&quot;ICG&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\n&lt;/td&gt;\n&lt;/tr&gt;\n&lt;tr&gt;\n&lt;td align=&quot;center&quot; valign=&quot;top&quot;&gt;\n&lt;table id=&quot;templateContainerImageCurve&quot; style=&quot;min-height: 15px;&quot; border=&quot;0&quot; width=&quot;100%&quot; cellspacing=&quot;0&quot; cellpaddi